NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'II Samuel'

CHAPTERS = {
    1: {
        1: 'Pripetilo se je torej, po Savlovi smrti, ko se je David vrnil iz pokola Amalečanov in je David dva dni prebival v Ciklágu',
        2: 'in tretji dan se je zgodilo celo, da je, glej, mož prišel iz tabora od Savla s svojimi pretrganimi oblačili in zemlja je bila na njegovi glavi. In bilo je tako, ko je prišel k Davidu, da je padel k tlom in se globoko priklonil.',
        3: 'David mu je rekel: »Od kod prihajaš?« Rekel mu je: »Pobegnil sem iz tabora Izraelcev.«',
        4: 'David mu je rekel: »Kako je šla zadeva? Prosim te, povej mi.« Odgovoril je: »Da je ljudstvo pobegnilo iz bitke in tudi številni izmed ljudstva so padli in so mrtvi in tudi Savel in njegov sin Jonatan sta mrtva.«',
        5: 'David je rekel mladeniču, ki mu je povedal: »Kako veš, da sta Savel in njegov sin Jonatan mrtva?«',
        6: 'Mladenič, ki mu je povedal, je rekel: »Kakor sem se naključno znašel na gori Gilbói, glej, Savel se je naslanjal na svojo sulico in glej, bojni vozovi in konjeniki so tesno sledili za njim.«',
        7: 'Ko je pogledal za seboj, me je videl in me poklical k sebi. Odgovoril sem: »Tukaj sem.«',
        8: 'Rekel mi je: »Kdo si?« Odgovoril sem mu: »Amálečan sem.«',
        9: 'Ponovno mi je rekel: »Stoj, prosim te, nad menoj in me ubij, kajti tesnoba je prišla nadme, ker je moje življenje še celo v meni.«',
        10: 'Tako sem stopil k njemu in ga usmrtil, ker sem bil prepričan, da potem, ko je padel, ne bi mogel živeti in vzel sem krono, ki je bila na njegovi glavi ter zapestnico, ki je bila na njegovem laktu ter ju prinesel sèm k svojemu gospodu.',
        11: 'Potem je David prijel svoja oblačila in jih raztrgal in prav tako vsi možje, ki so bili z njim',
        12: 'in žalovali so, jokali in se do večera postili za Savlom in za njegovim sinom Jonatanom in za Gospodovim ljudstvom in za Izraelovo hišo, ker so padli pod mečem.',
        13: 'David je rekel mladeniču, ki mu je povedal: »Od kod si?« Odgovoril je: »Jaz sem sin tujca, Amálečana.«',
        14: 'David mu je rekel: »Kako se nisi bal iztegniti svoje roke, da uničiš Gospodovega maziljenca?«',
        15: 'David je poklical enega izmed mladeničev ter rekel: »Približaj se in padi nanj.« In ta ga je udaril, da je umrl.',
        16: 'David mu je rekel: »Tvoja kri bodi na tvoji glavi, kajti tvoja usta so pričala zoper tebe, rekoč: ›Umoril sem Gospodovega maziljenca.‹«',
        17: 'David je s tem žalovanjem žaloval nad Savlom in nad njegovim sinom Jonatanom.',
        18: '(Prav tako je zaukazal, naj Judove otroke učijo uporabo loka. Glej, to je napisano v Jasherjevi knjigi.)',
        19: '»Izraelova lepota je umorjena na tvojih visokih krajih. Kako so padli mogočni!',
        20: 'Ne povejte tega v Gatu, ne razglašajte tega na Aškelónskih ulicah, da se ne bi filistejske hčere veselile, da ne bi hčere neobrezancev slavile.',
        21: 'Ve gore Gilbóe, naj tam ne bo nobene rose niti naj tam ne bo dežja nad vami niti nobenih polj za darovanja, kajti ščit mogočnega je podlo odvržen, Savlov ščit, kakor če ne bi bil maziljen z oljem.',
        22: 'Od krvi pobitih, od maščobe mogočnih, se Jonatanov lok ni obrnil nazaj in Savlov meč se ni vrnil prazen.',
        23: 'Savel in Jonatan sta bila očarljiva in prijetna v svojih življenjih in v svoji smrti nista bila ločena. Hitrejša sta bila kakor orli, močnejša sta bila kakor levi.',
        24: 'Ve hčere izraelske, jokajte nad Savlom, ki vas je oblekel v škrlat, z drugimi nasladami, ki je na vaše obleke nadel ornamente iz zlata.',
        25: 'Kako so mogočni padli v sredi bitke! Oh Jonatan, umorjen si bil na svojih visokih krajih.',
        26: 'Žalosten sem zaradi tebe, moj brat Jonatan. Zelo prijeten si mi bil. Tvoja ljubezen do mene je bila čudovita, presegajoča ljubezen žensk.',
        27: 'Kako so mogočni padli in so uničena bojna orožja.«',
    },
    2: {
        1: 'Pripetilo se je po tem, da je David poizvedel od Gospoda, rekoč: »Ali naj grem gor v katerokoli izmed Judovih mest?« Gospod mu je rekel: »Pojdi gor.« David mu je rekel: »Kam naj grem gor?« Rekel je: »V Hebrón.«',
        2: 'Tako je David odšel tja gor in tudi dve njegovi ženi: Jezreélka Ahinóam in Abigájila, žena Karmélčana Nabála.',
        3: 'Njegove može, ki so bili z njim, je David privedel gor, vsakega moža s svojo družino in prebivali so v mestih Hebróna.',
        4: 'Možje iz Juda so prišli in tam mazilili Davida [za] kralja nad Judovo hišo. In povedali so Davidu, rekoč: » Da so bili možje iz Jabéš Gileáda tisti, ki so pokopali Savla.«',
        5: 'David je poslal poslance k ljudem iz Jabéš Gileáda ter jim rekel: »Blagoslovljeni bodite od Gospoda, da ste izkazali to prijaznost našemu gospodu Savlu in ga pokopali.',
        6: 'Sedaj naj vam Gospod izkaže prijaznost in resnico in tudi jaz vam bom poplačal to prijaznost, ker ste storili to stvar.',
        7: 'Zato naj bodo sedaj vaše roke okrepljene in bodite hrabri, kajti vaš gospodar Savel je mrtev in tudi Judova hiša me je mazilila [za] kralja nad seboj.«',
        8: 'Toda Nerov sin Abnêr, poveljnik Savlove vojske, je vzel Savlovega sina Iš Bošeta, in ga privedel preko, v Mahanájim',
        9: 'in ga postavil [za] kralja nad Gileádom, nad Ašhúrci, nad Jezreélom, nad Efrájimom, nad Benjaminom in nad vsem Izraelom.',
        10: 'Savlov sin Iš Bošet je bil star štirideset let, ko je začel kraljevati nad Izraelom in kraljeval je dve leti. Toda Judova hiša je sledila Davidu.',
        11: 'In časa, ko je bil David kralj v Hebrónu, nad Judovo hišo, je bilo sedem let in šest mesecev.',
        12: 'In Nerov sin Abnêr in služabniki Savlovega sina Iš Bošeta so iz Mahanájima odšli v Gibeón.',
        13: 'In Cerújin sin Joáb in Davidovi služabniki so odšli ven in se srečali pri Gibeónskem ribniku in se usedli, eni na eni strani ribnika, drugi pa na drugi strani ribnika.',
        14: 'Abnêr je rekel Joábu: »Naj mladeniči sedaj vstanejo in igrajo pred nami.« Joáb je rekel: »Naj vstanejo.«',
        15: 'Potem so se tam vzdignili in odšli čez, po številu dvanajst iz Benjamina, ki je pripadal Iš Bošetovemu sinu Savlu in dvanajst izmed Davidovih služabnikov.',
        16: 'Vsak je zgrabil drugega za glavo in svoj meč porinil v njegovo stran. Tako so skupaj padli dol, zato je bil ta kraj imenovan Helkat-hazurim, ki je v Gibeónu.',
        17: 'Tam je bila ta dan zelo huda bitka in Abnêr je bil poražen in Izraelovi možje, pred Davidovimi služabniki.',
        18: 'Bili so trije Cerújini sinovi: Joáb, Abišáj in Asaél. Asaél je bil kakor svetloba stopala, kakor divja srna.',
        19: 'Asaél je zasledoval Abnêrja in ko je šel, se ni obrnil ne k desni roki niti ne k levi od zasledovanja Abnêrja.',
        20: 'Potem je Abnêr pogledal za seboj in rekel: » Ali si ti Asaél?« Odgovoril je: »Jaz sem.«',
        21: 'Abnêr mu je rekel: »Obrni se vstran k svoji desni roki ali k svoji levi in primi enega izmed mladeničev in si vzemi njegovo bojno opremo.« Toda Asaél se ni hotel obrniti od sledenja za njim.',
        22: 'Abnêr je ponovno rekel Asaélu: »Obrni se stran od sledenja za menoj. Zakaj bi te udaril k tlom? Kako bi potem svoj obraz dvignil k tvojemu bratu Joábu?«',
        23: 'Vendar je ta odklonil, da se obrne vstran. Zato ga je Abnêr z zadnjim delom sulice udaril pod petim rebrom, da je sulica pogledala ven za njim; in tam je padel dol in umrl na istem kraju. Pripetilo se je, da kolikor jih je prišlo na kraj, kjer je Asaél padel dol in umrl, da so mirno stali.',
        24: 'Tudi Joáb in Abišáj sta zasledovala Abnêrja. Sonce je zašlo, ko sta prišla k hribu Ame, ki leži pred Giahom, ob poti Gibeónske divjine.',
        25: 'Benjaminovi otroci so se zbrali skupaj za Abnêrjem in postali eno krdelo in stali na vrhu hriba.',
        26: 'Potem je Abnêr zaklical Joábu in rekel: »Mar bo meč požiral na veke? Ali ne veš, da bo v zadnjem koncu to grenkoba? Doklej bo torej, preden boš svojemu ljudstvu naročil, naj se vrne od zasledovanja svojih bratov?«',
        27: 'Joáb je rekel: » Kakor živi Bog, če ne bi spregovoril, bi potem zjutraj ljudstvo zagotovo odšlo gor, vsakdo od sledenja svojemu bratu.«',
        28: 'Tako je Joáb zatrobil na šofar in vse ljudstvo je mirno stalo in ni več zasledovalo Izraela niti se niso več bojevali.',
        29: 'Abnêr in njegovi možje so vso to noč hodili skozi ravnino in prečkali Jordan in šli skozi ves Bitrón in prišli do Mahanájima.',
        30: 'Joáb se je vrnil od zasledovanja Abnêrja in ko je vse ljudstvo zbral skupaj, je od Davidovih služabnikov manjkalo devetnajst mož in Asaél.',
        31: 'Toda Davidovi služabniki so udarili Benjaminove in Abnêrjeve može, tako da je umrlo tristo šestdeset mož.',
        32: 'Pobrali so Asaéla in ga pokopali v mavzoleju njegovega očeta, ki je bil v Betlehemu. Joáb in njegovi možje pa so vso noč hodili ter ob svitu prišli v Hebrón.',
    },
    3: {
        1: 'Torej tam je bila dolga vojna med Savlovo hišo in Davidovo hišo, toda David je postajal močnejši in močnejši, Savlova hiša pa je postajala šibkejša in šibkejša.',
        2: 'Davidu so se v Hebrónu rodili sinovi. Njegov prvorojenec je bil Amnón; od Jezreélke Ahinóam;',
        3: 'in njegov drugi Kiláb od Abigájile, žene Karmelčana Nabála in tretji Absalom, sin Maáhe, hčere gešurskega kralja Talmája;',
        4: 'in četrti Adoníja, Hagítin sin; in peti Šefatjá, sin Abitále;',
        5: 'in šesti Jitreám od Davidove žene Egle. Ti so bili rojeni Davidu v Hebrónu.',
        6: 'Pripetilo se je, medtem ko je bila vojna med Savlovo hišo in Davidovo hišo, da je Abnêr sebe naredil močnega za Savlovo hišo.',
        7: 'Savel je imel priležnico, ki ji je bilo ime Ricpa, Ajájeva hči in Iš Bošet je rekel Abnêrju: »Zakaj si odšel k priležnici mojega očeta?«',
        8: 'Potem je bil Abnêr zelo ogorčen zaradi besed Iš Bošeta in je rekel: » Mar sem pasja glava, ko ta dan zoper Juda izkazujem prijaznost hiši tvojega očeta Savla, njegovim bratom in njegovim prijateljem in te nisem izročil v Davidovo roko, da me danes obsojaš s krivdo glede te ženske?',
        9: 'Tako stori Bog Abnêrju in še več, razen če, kakor je Gospod prisegel Davidu, celo tako jaz storim njemu,',
        10: 'da se kraljestvo prestavi od Savlove hiše in da postavi Davidov prestol čez Izraela in čez Juda, od Dana, celo do Beeršébe.«',
        11: 'In ni mogel Abnêrju ponovno odgovoriti besede, ker se ga je bal.',
        12: 'Abnêr pa je v svojem imenu poslal poslance k Davidu, rekoč: »Čigava je ta dežela?« Rekoč tudi: »Skleni zavezo z menoj in glej, moja roka bo s teboj, da k tebi privedem ves Izrael.«',
        13: 'Rekel je: »Dobro. Jaz bom sklenil zavezo s teboj, toda od tebe zahtevam eno stvar, to je: ›Ne boš videl mojega obraza, razen če mi najprej ne pripelješ Savlove hčere Mihále, ko prideš, da vidiš moj obraz.‹«',
        14: 'David je poslal poslance k Savlovemu sinu Iš Bošetu, rekoč: »Izroči mi mojo ženo Mihálo, ki sem si jo zaročil za sto prednjih kožic Filistejcev.«',
        15: 'Iš Bošet je poslal in jo vzel od njenega soproga, torej od Lajiševega sina Paltíela.',
        16: 'Njen soprog je odšel skupaj z njo, jokajoč za njo, do Bahuríma. Potem mu je Abnêr rekel: »Pojdi, vrni se.« In se je vrnil.',
        17: 'Abnêr je imel pogovor z Izraelovimi starešinami, rekoč: »V preteklih časih ste iskali za Davidom, da bi bil kralj nad vami.',
        18: 'Sedaj torej to storite, kajti Gospod je govoril o Davidu, rekoč: ›Po roki svojega služabnika Davida bom rešil svoje ljudstvo Izraela iz roke Filistejcev in iz roke vseh njihovih sovražnikov.‹«',
        19: 'Abnêr je govoril tudi na ušesa Benjamina in Abnêr je odšel, da govori tudi na Davidova ušesa v Hebrónu. Vse to se je zdelo dobro Izraelu in to se je zdelo dobro celotni Benjaminovi hiši.',
        20: 'Tako je Abnêr prišel k Davidu v Hebrón in z njim dvajset mož. David je naredil zabavo za Abnêrja in može, ki so bili z njim.',
        21: 'Abnêr je rekel Davidu: »Vstal bom in šel in ves Izrael bom zbral k svojemu gospodu kralju, da bodo lahko s teboj sklenili zavezo in da boš lahko kraljeval nad vsem, kar si tvoje srce želi.« David je poslal Abnêrja proč in ta je odšel v miru.',
        22: 'Glej, Davidovi služabniki in Joáb so prišli iz zasledovanja krdela in s seboj prinesli velik plen, toda Abnêr ni bil z Davidom v Hebrónu, kajti poslal ga je proč in ta je odšel v miru.',
        23: 'Ko so prišli Joáb in vsa vojska, ki je bila z njim, so Joábu povedali, rekoč: »Nerov sin Abnêr je prišel h kralju in ta ga je poslal proč in je odšel v miru.«',
        24: 'Potem je Joáb prišel h kralju in rekel: »Kaj si storil? Glej, Abnêr je prišel k tebi. Zakaj je to, da si ga poslal proč in je on popolnoma izginil?',
        25: 'Ti poznaš Nerovega sina Abnêrja, da je prišel, da te zavede in da spozna tvoja odhajanja in tvoja prihajanja in da spozna vse, kar delaš.«',
        26: 'Ko je Joáb prišel od Davida, je za Abnêrjem poslal poslance, ki so ga ponovno privedli od vodnjaka Sire. Toda David tega ni vedel.',
        27: 'Ko se je Abnêr vrnil v Hebrón, ga je Joáb vzel na stran, v velika vrata, da bi tiho govoril z njim in ga tam udaril pod petim rebrom, da je umrl zaradi krvi njegovega brata Asaéla.',
        28: 'Potem ko je David to slišal, je rekel: »Jaz in moje kraljestvo sva brez krivde pred Gospodom na veke pred krvjo Nerovega sina Abnêrja.',
        29: 'Ta naj počiva na Joábovi glavi in na vsej hiši njegovega očeta in naj iz Joábove hiše ne zmanjka tistega, ki ima izliv ali je gobavec ali se naslanja na palico ali pada na meč ali mu primanjkuje kruha.«',
        30: 'Tako sta Joáb in njegov brat Abišáj umorila Abnêrja, ker je ubil njunega brata Asaéla v bitki pri Gibeónu.',
        31: 'David je rekel Joábu in vsemu ljudstvu, ki je bilo z njim: »Pretrgajte svoja oblačila in se opašite z vrečevino in žalujte pred Abnêrjem.« In sam kralj David je sledil mrtvaškemu odru.',
        32: 'Abnêrja so pokopali v Hebrónu. Kralj je povzdignil svoj glas in jokal nad Abnêrjevim grobom in vse ljudstvo je jokalo.',
        33: 'Kralj je žaloval nad Abnêrjem in rekel: »Je Abnêr umrl, kakor umira bedak?',
        34: 'Tvoje roke niso bile zvezane niti tvoja stopala, vklenjena v okove. Kakor mož pada pred zlobneži, tako padaš ti.« In vse ljudstvo je ponovno jokalo nad njim.',
        35: 'Ko je vse ljudstvo prišlo, da povzročijo Davidu, da jé hrano, medtem ko je bil še dan, je David prisegel, rekoč: »Tako naj mi Bog stori in še več, če okusim kruh ali karkoli drugega, dokler sonce ne zaide.«',
        36: 'Vse ljudstvo je to opazilo in to jim je ugajalo, kakor karkoli je kralj storil, je vsemu ljudstvu ugajalo.',
        37: 'Kajti vse ljudstvo in ves Izrael je ta dan razumelo, da to ni bilo od kralja, da umori Nerovega sina Abnêrja.',
        38: 'Kralj je rekel svojim služabnikom: »Ali ne veste, da je ta dan tukaj v Izraelu padel princ in velik mož?',
        39: 'Jaz sem ta dan šibek, čeprav maziljen kralj in ti možje, Cerújini sinovi, so pretežki zame. Gospod bo hudodelca nagradil glede na njegovo zlobnost.«',
    },
    4: {
        1: 'Ko je Savlov sin slišal, da je bil Abnêr mrtev v Hebrónu, so bile njegove roke slabotne in vsi Izraelci so bili zaskrbljeni.',
        2: 'Savlov sin je imel dva moža, ki sta bila poveljnika čet. Ime enega je bilo Baaná in ime drugega Reháb, sinova Rimóna, Beeróčana, izmed Benjaminovih otrok (kajti tudi Beerót je bil štet k Benjaminu',
        3: 'in Beeróčani so pobegnili v Gitájim in bili tam začasni prebivalci do tega dne.)',
        4: 'Savlov sin Jonatan je imel sina, ki je bil hrom od svojih stopal. Pet let je bil star, ko so prišle iz Jezreéla novice o Savlu in Jonatanu in njegova dojilja ga je vzela in pobegnila. Pripetilo pa se je, medtem ko je hitela, da pobegne, da je padel in postal hrom. Njegovo ime je bilo Mefibóšet.',
        5: 'Sinova Beeróčana Rimóna, Reháb in Baaná sta odšla in prišla okoli dnevne vročine v hišo Iš Bošeta, ki je opoldan ležal na postelji.',
        6: 'Prišla sta tja, v sredo hiše, kakor bi hotela vzeti pšenico. Udarila sta ga pod peto rebro in Reháb in njegov brat Baaná sta pobegnila.',
        7: 'Kajti ko sta prišla v hišo, je ležal na svoji postelji, v svoji spalnici in udarila sta ga in ga usmrtila in obglavila in vzela njegovo glavo in vso noč bežala čez ravnino.',
        8: 'Glavo Iš Bošeta sta prinesla k Davidu v Hebrón in rekla kralju: »Glej, glava Savlovega sina Iš Bošeta, tvojega sovražnika, ki je iskal tvoje življenje in Gospod je ta dan maščeval mojega gospoda kralja nad Savlom in njegovim semenom.«',
        9: 'David pa je odgovoril Rehábu in njegovemu bratu Baanáju, sinovoma Beeróčana Rimóna ter jima rekel: » Kakor živi Gospod, ki je mojo dušo odkupil od vseh nasprotnikov,',
        10: 'ko mi je nekdo povedal, rekoč: ›Glej, Savel je mrtev,‹ misleč, da je prinesel dobre novice, sem ga prijel in ga usmrtil v Ciklágu. Mislil je, da mu bom dal nagrado za njegove novice.',
        11: 'Koliko mnogo bolj, ko sta zlobneža umorila pravično osebo v njegovi lastni hiši, na njegovi postelji? Mar ne bom torej sedaj zahteval njegovo kri iz vajine roke in vaju vzel proč z zemlje?«',
        12: 'David je svojim mladeničem zapovedal in so ju ubili ter odsekali njuni roki in njuna stopala in ju obesili gor nad ribnik v Hebrónu. Toda vzeli so glavo Iš Bošeta in jo pokopali v Abnêrjevem mavzoleju v Hebrónu.',
    },
    5: {
        1: 'Potem so vsi Izraelovi rodovi prišli k Davidu v Hebrón in spregovorili, rekoč: »Glej, mi smo tvoja kost in tvoje meso.',
        2: 'Tudi v preteklem času, ko je bil Savel kralj nad nami, si bil ti tisti, ki nas je vodil ven in privedel v Izrael in Gospod ti je rekel: ›Ti boš pasel moje ljudstvo Izrael in ti boš poveljnik nad Izraelom.‹«',
        3: 'Tako so vsi Izraelovi starešine prišli h kralju v Hebrón in kralj David je z njimi v Hebrónu sklenil zavezo pred Gospodom in Davida so mazilili [za] kralja nad Izraelom.',
        4: 'David je bil star trideset let, ko je začel kraljevati in kraljeval je štirideset let.',
        5: 'V Hebrónu je nad Judom kraljeval sedem let in šest mesecev, v Jeruzalemu pa je triintrideset let kraljeval nad vsem Izraelom in Judom.',
        6: '§ Kralj in njegovi možje so odšli v Jeruzalem k Jebusejcem, prebivalcem dežele, ki so Davidu spregovorili, rekoč: »Razen če ne odstraniš slepih in hromih, ne boš vstopil sèm,« misleč, [da] David ne more priti tja.',
        7: 'Kljub temu je David zavzel oporišče Sion. Isto je Davidovo mesto.',
        8: 'David je na ta dan rekel: »Kdorkoli se spravi gor do jarka in udari Jebusejce in hrome in slepe, ki jih Davidova duša sovraži, ta bo voditelj in poveljnik.« Zatorej so rekli: »Slepi in hromi ne bodo prišli v hišo.«',
        9: 'Tako je David prebival v utrdbi in jo imenoval Davidovo mesto. In David je gradil naokoli od Milója in znotraj.',
        10: 'David je odšel naprej in postal velik in Gospod, Bog nad bojevniki, je bil z njim.',
        11: 'Tirski kralj Hirám je poslal poslance k Davidu in cedrova drevesa, tesarje in zidarje in ti so Davidu zgradili hišo.',
        12: 'David je zaznal, da ga je Gospod utrdil za kralja nad Izraelom in da je njegovo kraljestvo povišal zaradi svojega ljudstva Izraela.',
        13: 'In David si je vzel [še] več priležnic in žená iz Jeruzalema, potem ko je prišel iz Hebróna in tam so se Davidu rodili še sinovi in hčere.',
        14: 'To so imena izmed tistih, ki so mu bili rojeni v Jeruzalemu: Šamúa, Šobáb, Natán, Salomon,',
        15: 'tudi Jibhár, Elišúa, Nefeg, Jafíja,',
        16: 'Elišamá, Eljadá in Elifálet.',
        17: 'Toda ko so Filistejci slišali, da so Davida mazilili [za] kralja nad Izraelom, so vsi Filistejci prišli gor, da poiščejo Davida in David je slišal o tem in odšel dol k utrjenemu kraju.',
        18: 'Tudi Filistejci so prišli in se razkropili v dolini Rafájim.',
        19: 'David je poizvedel od Gospoda, rekoč: »Naj grem gor k Filistejcem? Jih boš izročil v mojo roko?« Gospod je rekel Davidu: »Pojdi gor, kajti nedvomno bom Filistejce izročil v tvojo roko.«',
        20: 'David je prišel do Báal Peracíma in David jih je tam udaril ter rekel: » Gospod je kakor prodor vodá izbruhnil na moje sovražnike pred menoj.« Zato je ime tega kraja imenoval Báal Peracím.',
        21: '§ In oni so tam pustili svoje podobe, David in njegovi možje pa so jih sežgali.',
        22: 'In Filistejci so ponovno prišli gor in se razkropili v dolini Rafájim.',
        23: 'Ko je David poizvedel od Gospoda, je rekel: »Ne boš šel gor, temveč za njimi postavi zasedo in pridi nadnje nasproti murvinim drevesom.',
        24: 'In naj bo, ko zaslišiš šum hoje v vrhu murvinih dreves, da se boš potem podvizal, kajti takrat bo Gospod šel ven pred teboj, da udari vojsko Filistejcev.«',
        25: 'David je storil tako, kakor mu je Gospod zapovedal in udarjal Filistejce od Gebe, dokler ne prideš do Gazerja.',
    },
    6: {
        1: 'David je ponovno zbral skupaj vse izbrane može iz Izraela, trideset tisoč.',
        2: 'In David je vstal in z vsem ljudstvom, ki je bilo z njim, odšel od Baále Judove, da od tam prinese gor Božjo skrinjo, katere ime je imenovano po imenu Gospoda nad bojevniki, ki prebiva med kerubi.',
        3: 'Božjo skrinjo so postavili na nov voz in jo privedli iz Abinadábove hiše, ki je bila v Gíbei. Abinadábova sinova Uzá in Ahjó pa sta gnala nov voz.',
        4: 'Prinesli so jo iz Abinadábove hiše, ki je bila v Gíbei, spremljajoč Božjo skrinjo in Ahjó je šel pred skrinjo.',
        5: 'David in vsa Izraelova hiša pa so igrali pred Gospodom na vse vrste glasbil, narejenih iz cipresovega lesa, celo na harfe, na plunke, na tamburine, na kornéte in na cimbale.',
        6: 'In ko so prišli do Nahónovega mlatišča, je Uzá iztegnil svojo roko k Božji skrinji in jo prijel, kajti voli so jo tresli.',
        7: 'Gospodova jeza je bila vžgana zoper Uzája in Bog ga je tam udaril zaradi njegove napake; in tam je umrl, ob Božji skrinji.',
        8: 'David je bil razžaljen, ker je Gospod naredil vrzel nad Uzájem, in ime tega mesta je imenoval Perec Uzá do tega dne.',
        9: 'David se je tisti dan zbal Gospoda in rekel: »Kako bo Gospodova skrinja prišla k meni?«',
        10: 'Tako David Gospodove skrinje ni hotel prestaviti k sebi v Davidovo mesto, temveč jo je David odvedel vstran, v hišo Gitéjca Obéd Edóma.',
        11: 'In Gospodova skrinja je tri mesece ostala v hiši Gitéjca Obéd Edóma in Gospod je blagoslovil Obéd Edóma in vso njegovo družino.',
        12: 'To je bilo sporočeno kralju Davidu, rekoč: » Gospod je zaradi Božje skrinje blagoslovil hišo Obéd Edóma in vse, kar mu pripada.« Tako je David šel in z veseljem prinesel gor Božjo skrinjo iz hiše Obéd Edóma v Davidovo mesto.',
        13: 'In bilo je tako, da ko so tisti, ki so nosili Gospodovo skrinjo, naredili šest korakov, je žrtvoval vole in pitance.',
        14: 'David je z vso svojo močjo plesal pred Gospodom in David je bil opasan z lanenim efódom.',
        15: 'Tako so David in vsa Izraelova hiša z vriskanjem in z zvokom šofarja Gospodovo skrinjo prinesli gor.',
        16: 'Ko je Gospodova skrinja prišla v Davidovo mesto, je Savlova hči Mihála pogledala skozi okno in videla kralja Davida skakati in plesati pred Gospodom in ga prezirala v svojem srcu.',
        17: 'In prinesli so Gospodovo skrinjo in jo postavili na njen kraj, v sredo šotorskega svetišča, ki ga je David razpel zanjo in David je pred Gospodom daroval žgalne daritve in mirovne daritve.',
        18: 'Takoj, ko je David prenehal darovati žgalne daritve in mirovne daritve, je v imenu Gospoda nad bojevniki blagoslovil ljudstvo.',
        19: 'Med vse ljudstvo je razdelil, celó med celotno Izraelovo množico, tako ženskam kakor moškim, vsakomur kolač kruha, dober kos mesa in flaškon vina. Tako je vse ljudstvo odšlo vsak k svoji hiši.',
        20: 'Potem se je David vrnil, da blagoslovi svojo družino. Savlova hči Mihála pa je prišla ven, da sreča Davida in rekla: »Kako veličasten je bil danes Izraelov kralj, ki se je danes razkril pred očmi pomočnic svojih služabnikov, kakor se brezsramno razkriva nekdo izmed nadutih pajdašev.«',
        21: 'David je rekel Miháli: » To je bilo pred Gospodom, ki me je izbral pred tvojim očetom in pred vso njegovo hišo, da me določi [za] vladarja nad Gospodovim ljudstvom, nad Izraelom. Zato bom igral pred Gospodom.',
        22: 'In še bolj se bom pomanjšal kakor to in bom ponižen v svojem lastnem pogledu. Glede dekel pa, o katerih si govorila, od njih bom imel spoštovanje.«',
        23: 'Zato Savlova hči Mihála ni imela nobenega otroka do dneva svoje smrti.',
    },
    7: {
        1: 'Pripetilo se je, ko je kralj sedel v svoji hiši in mu je vsenaokrog Gospod dal počitek, od vseh njegovih sovražnikov,',
        2: 'da je kralj rekel preroku Natánu: »Poglej torej, jaz prebivam v cedrovi hiši, toda Božja skrinja prebiva znotraj zaves.«',
        3: 'Natán je rekel kralju: »Pojdi, stori vse, kar je v tvojem srcu, kajti Gospod je s teboj.«',
        4: 'To noč pa se je pripetilo, da je beseda od Gospoda prišla Natánu, rekoč:',
        5: '»Pojdi in povej mojemu služabniku Davidu: ›Tako govori Gospod: ›Mar mi boš zgradil hišo, da prebivam v njej?',
        6: 'Medtem ko nisem prebival v katerikoli hiši od časa, ko sem Izraelove otroke privedel iz Egipta, celo do tega dne, temveč sem hodil v šotoru in v šotorskem svetišču.',
        7: 'Na vseh krajih, kjer sem hodil z vsemi Izraelovimi otroki, sem mar govoril besedo s katerimkoli izmed Izraelovih rodov, ki sem jim zapovedal, naj pasejo moje ljudstvo Izraela, rekoč: ›Zakaj mi ne zgradite cedrove hiše?‹',
        8: 'Sedaj boš torej tako rekel mojemu služabniku Davidu: ›Tako govori Gospod nad bojevniki: ›Vzel sem te iz ovčje staje, od sledenja za ovcami, da bi bil vladar nad mojim ljudstvom, nad Izraelom.',
        9: 'In bil sem s teboj kamorkoli si šel in odsekal sem vse tvoje sovražnike izpred tvojega pogleda in naredil sem ti veliko ime, podobno imenu velikih mož, ki so na zemlji.',
        10: 'Poleg tega bom določil kraj za svoje ljudstvo Izrael in jih zasadil, da bodo lahko prebivali na svojem lastnem kraju in se ne bodo več selili; niti jih otroci zlobnosti ne bodo več stiskali kakor poprej',
        11: 'in kot že od časa, ko sem sodnikom zapovedal, naj bodo nad mojim ljudstvom Izraelom in sem ti dal, da počivaš pred vsemi svojimi sovražniki.‹ In Gospod ti tudi govori, da ti bo naredil hišo.',
        12: 'Ko bodo tvoji dnevi izpolnjeni in boš zaspal s svojimi očeti, bom postavil tvoje seme za teboj, ki bo izšlo iz tvoje notranjosti in jaz bom osnoval njegovo kraljestvo.',
        13: 'On bo zgradil hišo mojemu imenu in jaz bom na veke osnoval prestol njegovega kraljestva.',
        14: 'Jaz bom njegov oče in on bo moj sin. Če stori krivičnost, ga bom karal s človeško šibo in z udarci človeških otrok,',
        15: 'toda moje usmiljenje ne bo odšlo proč od njega, kakor sem ga vzel od Savla, ki sem ga odstranil pred teboj.',
        16: 'Tvoja hiša in tvoje kraljestvo bo pred teboj osnovano na veke. Tvoj prestol bo osnovan na veke.‹«',
        17: 'Glede na vse te besede in glede na vse to videnje, tako je Natán govoril Davidu.',
        18: 'Potem je vstopil kralj David in se usedel pred Gospodom ter rekel: »Kdo sem jaz, oh Gospod Bog? In kaj je moja hiša, da si me privedel do tu?',
        19: 'In to je bila še majhna stvar v tvojem pogledu, oh Gospod Bog, toda govoril si tudi o hiši tvojega služabnika za oddaljeni čas, ki pride. Ali je to človeški način, oh Gospod Bog?',
        20: 'Kaj ti še lahko reče David? Kajti ti, Gospod Bog, poznaš svojega služabnika.',
        21: 'Zaradi svojih besed in glede na svoje lastno srce si storil vse te velike stvari, da pripraviš svojega služabnika, da jih pozna.',
        22: 'Zakaj ti si velik, oh Gospod Bog, kajti nikogar ni podobnega tebi niti ni nobenega Boga poleg tebe, glede na vse, kar smo slišali z svojimi ušesi.',
        23: 'In kateri narod na zemlji je podoben tvojemu ljudstvu, celó podoben Izraelu, ki ga je Bog odšel odkupit za svoje ljudstvo in da mu naredi ime in da za vas stori velike stvari in strašne, za tvojo deželo, pred tvojim ljudstvom, ki si ga iz Egipta odkupil k sebi, pred narodi in njihovimi bogovi?',
        24: 'Kajti ti si si potrdil svoje ljudstvo Izrael, da ti bo ljudstvo na veke, in ti, Gospod, si postal njihov Bog.',
        25: 'Sedaj, oh Gospod Bog, beseda, ki si jo spregovoril glede svojega služabnika in glede svoje hiše, utrdi jo na veke in stôri, kakor si rekel.',
        26: 'Tvoje ime naj bo poveličano na veke, rekoč: › Gospod nad bojevniki je Bog nad Izraelom in hiša tvojega služabnika Davida naj bo osnovana pred teboj.‹',
        27: 'Kajti ti, oh Gospod nad bojevniki, Izraelov Bog, si razodel svojemu služabniku, rekoč: ›Zgradil ti bom hišo.‹ Zato je tvoj služabnik odkril v svojem srcu, da k tebi moli to molitev.',
        28: 'In sedaj, oh Gospod Bog, ti si ta Bog in tvoje besede so resnične in svojemu služabniku si obljubil to dobroto,',
        29: 'zato naj ti sedaj ugaja, da blagosloviš hišo svojega služabnika, da bo ta lahko na veke trajala pred teboj, kajti ti, oh Gospod Bog, si to govoril in s tvojim blagoslovom naj bo hiša tvojega služabnika blagoslovljena na veke.«',
    },
    8: {
        1: 'Po tem se je pripetilo, da je David udaril Filistejce in jih podjarmil. David je vzel Meteg–amo iz roke Filistejcev.',
        2: 'Udaril je Moábce in jih premeril z vrvico, [medtem ko] jih je vrgel na tla. Celo z dvema vrvicama je premeril, da jih usmrti in z eno polno vrvico, da jih ohrani žive. Tako so Moábci postali Davidovi služabniki in prinašali darila.',
        3: 'David je udaril tudi Rehóbovega sina Hadadézerja, kralja iz Cobe, ko je odšel, da obnovi svojo mejo pri reki Evfratu.',
        4: 'David je od njega vzel tisoč bojnih voz, sedemsto konjenikov in dvajset tisoč pešcev in David je prerezal Ahilove tetive vsem konjem bojnih vozov, toda izmed njih jih je prihranil za sto bojnih vozov.',
        5: 'Ko so prišli Sirci iz Damaska, da okrepijo Hadadézerja, kralja iz Cobe, je David izmed Sircev usmrtil dvaindvajset tisoč mož.',
        6: 'Potem je David postavil garnizije v Siriji, v Damasku in Sirci so postali Davidovi služabniki in prinašali darila. In Gospod je varoval Davida kamorkoli je odšel.',
        7: 'David je vzel ščite iz zlata, ki so bili na Hadadézerjevih služabnikih in jih prinesel v Jeruzalem.',
        8: 'Iz Betaha in iz Berotája, Hadadézerjevih mest, je kralj David vzel silno veliko brona.',
        9: 'Ko je Toí, kralj Hamáta, slišal, da je David udaril vso Hadadézerjevo vojsko,',
        10: 'potem je Toí poslal h kralju Davidu svojega sina Joráma, da ga pozdravi in da ga blagoslovi, ker se je bojeval zoper Hadadézerja in ga udaril, kajti Hadadézer je imel vojne s Toíjem. In Jorám je s seboj prinesel posode iz srebra, posode iz zlata in posode iz brona,',
        11: 'ki jih je tudi kralj David posvetil Gospodu, skupaj s srebrom in zlatom, ki ga je posvetil od vseh narodov, ki jih je podjarmil;',
        12: 'od Sirije in od Moába in od Amónovih otrok in od Filistejcev in od Amáleka in od Hadadézerjevega plena, Rehóbovega sina, kralja Cobe.',
        13: 'David si je pridobil ime, ko se je vrnil iz udarjanja Sircev v solni dolini, ki jih je bilo osemnajst tisoč mož.',
        14: 'Postavil je garnizije v Edómu, po vsem Edómu je postavil garnizije in vsi tisti iz Edóma so postali Davidovi služabniki. In Gospod je varoval Davida kamorkoli je šel.',
        15: 'David je kraljeval nad vsem Izraelom in David je izvajal sodbo in pravico vsemu svojemu ljudstvu.',
        16: 'Cerújin sin Joáb je bil nad vojsko, Ahilúdov sin Józafat je bil letopisec,',
        17: 'Ahitúbov sin Cadók in Abjatárjev sin Ahiméleh sta bila duhovnika, Serajá je bil pisar,',
        18: 'Jojadájev sin Benajá je bil tako nad Keretéjci in Péletovci, Davidovi sinovi pa so bili glavni vladarji.',
    },
    9: {
        1: 'David je rekel: »Je še kakšen, ki je preostal od Savlove hiše, da mu lahko zaradi Jonatana izkažem prijaznost?«',
        2: 'Bil pa je iz Savlove hiše služabnik, katerega ime je bilo Cibá. Ko so ga poklicali k Davidu, mu je kralj rekel: » Si ti Cibá?« Rekel je: » On je tvoj služabnik.«',
        3: 'Kralj je rekel: » Mar ni nikogar več iz Savlove hiše, da mu lahko izkažem Božjo prijaznost?« Cibá je kralju rekel: »Jonatan ima še sina, ki je hrom na svojih stopalih.«',
        4: 'Kralj mu je rekel: »Kje se nahaja?« Cibá je rekel kralju: »Glej, v hiši Amiélovega sina Mahírja v Lo Dabárju je.«',
        5: 'Potem je kralj David poslal in ga privedel iz hiše Amiélovega sina Mahírja, iz Lo Dabárja.',
        6: 'Torej ko je Mefibóšet, sin Jonatana, Savlovega sina, prišel k Davidu, je padel na svoj obraz in ga počastil. David je rekel: »Mefibóšet.« Odgovoril je: »Glej, tvoj služabnik!«',
        7: 'David mu je rekel: »Ne boj se, kajti zagotovo ti bom izkazal prijaznost zaradi tvojega očeta Jonatana in jaz ti bom obnovil vso deželo tvojega očeta Savla in pri moji mizi boš nenehno jedel kruh.«',
        8: 'Priklonil se je in rekel: »Kaj je tvoj služabnik, da bi pogledal na takšnega mrtvega psa, kot sem jaz?«',
        9: 'Potem je kralj poklical Savlovega služabnika Cibája in mu rekel: »Sinu tvojega gospodarja sem izročil vse, kar je pripadalo Savlu in vsej njegovi hiši.',
        10: 'Torej ti in tvoji sinovi in tvoji služabniki, boste zanj obdelovali deželo in ti boš prinesel sadove, da bo sin tvojega gospodarja lahko imel hrano za jesti. Toda Mefibóšet, sin tvojega gospodarja, bo vedno jedel kruh pri moji mizi.« Torej Cibá je imel petnajst sinov in dvajset služabnikov.',
        11: 'Potem je Cibá rekel kralju: »Glede na vse, kar je moj gospod kralj zapovedal svojemu služabniku, tako bo tvoj služabnik storil. Kar se tiče Mefibóšeta,« je rekel kralj, »on bo jedel pri moji mizi, kakor nekdo izmed kraljevih sinov.«',
        12: 'Mefibóšet pa je imel mladega sina, katerega ime je bilo Miha. In vsi, ki so prebivali v Cibájajevi hiši, so bili služabniki Mefibóšetu.',
        13: 'Tako je Mefibóšet prebival v Jeruzalemu, kajti nenehno je jedel pri kraljevi mizi, bil pa je hrom na obeh svojih stopalih.',
    },
    10: {
        1: 'Potem se je pripetilo, da je umrl kralj Amónovih otrok in namesto njega je zakraljeval njegov sin Hanún.',
        2: 'Potem je David rekel: »Prijaznost bom izkazal Naháševemu sinu Hanúnu, kot je njegov oče izkazal prijaznost meni.« In David je poslal, da ga potolaži po roki svojih služabnikov, zaradi njegovega očeta. In Davidovi služabniki so prišli v deželo Amónovih otrok.',
        3: 'Princi Amónovih otrok pa so rekli svojemu gospodarju Hanúnu: »Misliš, da David spoštuje tvojega očeta, da je k tebi poslal tolažnike? Ali ni David raje svojih služabnikov poslal k tebi, da bi preiskal mesto, vohunil in da ga zruši?«',
        4: 'Zato je Hanún vzel Davidove služabnike, jim pobril eno polovico njihovih brad in njihove obleke odrezal po sredi, celó do njihovih zadnjic in jih poslal proč.',
        5: 'Ko so to povedali Davidu, je poslal, da jih sreča, ker so bili možje silno osramočeni. Kralj je rekel: »Ostanite pri Jerihi, dokler vam brade ne zrastejo in potem se vrnite.«',
        6: 'Ko so Amónovi otroci videli, da so se usmradili pred Davidom, so Amónovi otroci poslali in najeli Sirce iz Bet Rehóba, Sirce iz Cobe, dvajset tisoč pešcev in od kralja Maáhe tisoč mož in iz Toba dvanajst tisoč mož.',
        7: 'Ko je David slišal o tem, je poslal Joába in vso vojsko mogočnih mož.',
        8: 'Amónovi otroci so prišli ven in se postrojili v bitko ob vhodu velikih vrat. Sirci iz Cobe, iz Rehóba, Toba in Maáhe pa so bili posebej na polju.',
        9: 'Ko je Joáb videl, da je bilo čelo bitke zoper njega spredaj in zadaj, je izbral izmed vseh izbranih Izraelovih mož in jih postrojil zoper Sirce.',
        10: 'Preostanek ljudstva pa je izročil v roko svojega brata Abišája, da bi jih lahko postrojil zoper Amónove otroke.',
        11: 'Rekel je: »Če bodo Sirci zame premočni, potem boš ti pomagal meni, toda če bodo Amónovi otroci premočni zate, potem bom prišel in ti pomagal.',
        12: 'Bodi odločnega poguma in bodimo možje za naše ljudstvo in za mesta našega Boga, Gospod pa naj stori to, kar se mu zdi dobro.«',
        13: 'Joáb se je približal in ljudstvo, ki je bilo z njim, k bitki zoper Sirce in ti so pobegnili pred njim.',
        14: 'Ko so Amónovi otroci videli, da so Sirci pobegnili, potem so tudi sami pobegnili pred Abišájem in vstopili v mesto. Tako se je Joáb vrnil od Amónovih otrok in prišel v Jeruzalem.',
        15: 'Ko so Sirci videli, da so bili udarjeni pred Izraelom, so se zbrali skupaj.',
        16: 'Hadarézer je poslal in privedel ven Sirce, ki so bili onkraj reke in prišli so do Heláma in Šobáh, poveljnik Hadarézerjeve vojske, je šel pred njimi.',
        17: 'Ko je bilo to povedano Davidu, je zbral skupaj ves Izrael in prečkal Jordan ter prišel k Helámu. Sirci pa so se postrojili zoper Davida in se borili z njim.',
        18: 'In Sirci so pobegnili pred Izraelom, in David je usmrtil sedemsto mož sirskih bojnih vozov in štirideset tisoč konjenikov in udaril Šobáha, poveljnika njihove vojske, ki je tam umrl.',
        19: 'Ko so vsi kralji, ki so bili Hadarézerjevi služabniki, videli, da so bili udarjeni pred Izraelom, so z Izraelom sklenili mir in jim služili. Tako so se Sirci bali, da bi še pomagali Amónovim otrokom.',
    },
    11: {
        1: 'Pripetilo se je, potem ko je minilo leto, ob času, ko gredo kralji na bitko, da je David poslal Joába in z njim svoje služabnike in ves Izrael in uničili so Amónove otroke in oblegali Rabo. Toda David se je še vedno zadrževal v Jeruzalemu.',
        2: 'Ob večernem času se je pripetilo, da se je David dvignil iz svoje postelje in hodil po strehi kraljeve hiše in s strehe je videl žensko, ki se je umivala in ženska je bila na pogled zelo krasna.',
        3: 'David je poslal in poizvedel za žensko. Nekdo je rekel: » Mar ni to Batšéba, Eliámova hči, žena Hetejca Urijája?«',
        4: 'David je poslal poslance in jo vzel. Vstopila je k njemu in ležal je z njo, kajti očiščena je bila od svoje nečistosti in vrnila se je v svojo hišo.',
        5: 'Ženska je spočela in poslala in povedala Davidu ter rekla: »Jaz sem z otrokom.«',
        6: 'David je poslal k Joábu, rekoč: »Pošlji mi Hetejca Urijája.« In Joáb je poslal Urijája k Davidu.',
        7: 'Ko je Urijá prišel k njemu, je David od njega zahteval, kako je šlo Joábu in kako je šlo ljudstvu in kako je uspevala vojna.',
        8: 'David je Urijáju rekel: »Pojdi dol k svoji hiši in si umij stopala.« Urijá je odšel iz kraljeve hiše in sledilo mu je darilo kraljeve jedi.',
        9: 'Toda Urijá je spal pri vratih kraljeve hiše z vsemi služabniki svojega gospoda in ni odšel dol k svoji hiši.',
        10: 'Ko so Davidu povedali, rekoč: »Urijá ni odšel dol k svoji hiši,« je David rekel Urijáju: »Ali ne prihajaš iz svojega potovanja? Zakaj potem nisi šel dol k svoji hiši?«',
        11: 'Urijá je Davidu rekel: »Skrinja, Izrael in Juda prebivajo v šotorih in moj gospod Joáb in služabniki mojega gospoda so utaborjeni na odprtih poljih; ali bom jaz potem šel v svojo hišo, da jem, da pijem in da ležim s svojo ženo? Kakor ti živiš in kakor živi tvoja duša, ne bom storil te stvari.«',
        12: 'In David je rekel Urijáju: »Ostani tukaj tudi danes, jutri pa ti bom pustil oditi.« Tako je Urijá ostal v Jeruzalemu ta dan in naslednji dan.',
        13: 'Ko ga je David poklical, je pred njim jedel in pil in ga je opijanil in zvečer je odšel ven, da bi s služabniki svojega gospoda legel na svojo posteljo, toda ni šel dol k svoji hiši.',
        14: 'Zjutraj pa se je zgodilo, da je David napisal pismo Joábu in to poslal po Urijájevi roki.',
        15: 'V pismu je napisal, rekoč: »Postavite Urijája na sprednji del najbolj vroče bitke in se umaknite od njega, da bo lahko udarjen in umre.«',
        16: 'Pripetilo se je, ko je Joáb opazoval mesto, da je Urijája določil na kraj, kjer je vedel, da so bili hrabri možje.',
        17: 'Možje iz mesta so odšli ven in se borili z Joábom in tam so padli nekateri izmed ljudstva, izmed Davidovih služabnikov in tudi Hetejec Urijá je umrl.',
        18: 'Potem je Joáb poslal in Davidu povedal vse stvari glede vojne',
        19: 'in naročil poslancu, rekoč: »Ko boš končal s sporočanjem stvari kralju glede vojne',
        20: 'in če bo tako, da se bo vzdignil kraljevi bes in ti reče: ›Zakaj ste se približali tako blizu mesta, ko ste se bojevali? Mar niste vedeli, da bodo streljali iz obzidja?',
        21: 'Kdo je udaril Jerubéšetovega sina Abiméleha? Ali ni ženska iz obzidja vrgla nanj kos mlinskega kamna, da je umrl v Tebécu? Zakaj ste se približali obzidju?‹ Potem reci: ›Tudi tvoj služabnik Hetejec Urijá je mrtev.‹«',
        22: 'Tako je poslanec odšel in prišel in pokazal Davidu vse, za kar ga je Joáb poslal.',
        23: 'Poslanec je Davidu rekel: »Ljudje so zagotovo prevladali zoper nas in prišli ven, k nam na polje in mi smo bili nad njimi celo do vhoda velikih vrat.',
        24: 'In strelci so streljali iz obzidja na tvoje služabnike; in nekateri izmed kraljevih služabnikov so mrtvi in tudi tvoj služabnik Hetejec Urijá je mrtev.«',
        25: 'Potem je David rekel poslancu: »Tako boš rekel Joábu: ›Ne dopusti, da te ta stvar razžali, kajti meč požre enega kakor drugega. Svojo bitko zoper mesto naredi močnejšo in ga premagaj. Ohrabri ga.‹«',
        26: 'Ko je Urijájeva žena slišala, da je bil njen soprog Urijá mrtev, je žalovala za svojim soprogom.',
        27: 'Ko je žalovanje minilo, je David poslal in jo privedel k svoji hiši in postala je njegova žena in mu rodila sina. Toda stvar, ki jo je David storil, je razžalila Gospoda.',
    },
    12: {
        1: 'Gospod je k Davidu poslal Natána. Ta je prišel k njemu in mu rekel: »Bila sta dva moža v enem mestu; eden bogat, drugi pa reven.',
        2: 'Bogat človek je imel silno mnogo tropov in čred,',
        3: 'toda reven človek ni imel ničesar, razen ene majhne ovčje jagnjice, ki jo je kupil in jo preživljal. Ta je zrasla skupaj z njim in z njegovimi otroki; jedla je od njegove lastne hrane, pila iz njegove lastne čaše, ležala v njegovem naročju in mu je bila kakor hči.',
        4: 'K bogatašu pa je prišel popotnik in žal mu je bilo vzeti od svojega lastnega tropa in od svoje lastne črede, da pripravi za popotnika, ki je prišel k njemu, temveč je vzel reveževo jagnje in to pripravil za človeka, ki je prišel k njemu.«',
        5: 'Davidova jeza je bila silno vžgana zoper tega moža in Natánu je rekel: » Kakor Gospod živi, mož, ki je storil to stvar, bo zagotovo umrl',
        6: 'in četverno bo povrnil jagnje, ker je storil to stvar in ker ni imel usmiljenja.«',
        7: 'Natán je rekel Davidu: »Ti si ta človek. Tako govori Gospod, Izraelov Bog: ›Mazilil sem te [za] kralja nad Izraelom in te osvobodil iz Savlove roke.',
        8: 'Dal sem ti hišo tvojega gospodarja in v tvoje naročje žene tvojega gospodarja in dal sem ti Izraelovo in Judovo hišo. Če bi bilo to premalo, bi ti dodal še več takšnih in takšnih stvari.',
        9: 'Zakaj si preziral Gospodovo zapoved, da si storil zlo v njegovem pogledu? Hetejca Urijája si ubil z mečem in njegovo ženo vzel, da postane tvoja žena, njega pa si umoril z mečem Amónovih otrok.',
        10: 'Zdaj torej meč ne bo nikoli odšel od tvoje hiše, ker si me preziral in si vzel ženo Hetejca Urijája, da bi bila tvoja žena.‹',
        11: 'Tako govori Gospod: ›Glej, zoper tebe bom vzdignil zlo iz tvoje lastne hiše in pred tvojimi očmi bom vzel tvoje žene in jih dal tvojemu bližnjemu in ta bo ležal s tvojimi ženami v pogledu tega sonca.',
        12: 'Kajti ti si to delal naskrivaj, toda jaz bom to stvar storil pred vsem Izraelom in pred soncem.‹«',
        13: 'David je rekel Natánu: »Grešil sem zoper Gospoda.« Natán je rekel Davidu: » Gospod je tudi odstranil tvoj greh; ne boš umrl.',
        14: 'Vendar ker si s tem dejanjem dal Gospodovim sovražnikom veliko priložnost, da izrekajo bogokletje, bo tudi otrok, ki ti je rojen, zagotovo umrl.«',
        15: 'In Natán je odšel od njegove hiše. Gospod pa je udaril otroka, ki ga je Urijájeva žena rodila Davidu in ta je bil zelo bolan.',
        16: 'David je zato rotil Boga za otroka in David se je postil in vstopil ter vso noč ležal na zemlji.',
        17: 'Starešine njegove hiše so vstali in odšli k njemu, da ga vzdignejo z zemlje, toda ni hotel niti ni z njimi jedel kruha.',
        18: 'Pripetilo se je na sedmi dan, da je otrok umrl. Davidovi služabniki pa so se mu bali povedati, da je bil otrok mrtev, kajti rekli so: »Glej, medtem ko je bil otrok še živ, smo mu govorili, pa ni hotel poslušati našega glasu. Kako bo torej žalostil samega sebe, če mu povemo, da je otrok mrtev?«',
        19: 'Toda ko je David videl, da so njegovi služabniki šepetali, je David zaznal, da je bil otrok mrtev. Zato je David rekel svojim služabnikom: »Je otrok mrtev?« Rekli so: »Mrtev je.«',
        20: 'Potem se je David vzdignil z zemlje, se umil, mazilil, zamenjal svojo obleko, prišel v Gospodovo hišo in oboževal. Potem je prišel v svojo lastno hišo; in ko je zahteval, so predenj postavili kruh in je jedel.',
        21: 'Potem so mu njegovi služabniki rekli: »Kakšna stvar je ta, ki si jo storil? Postil si se in jokal zaradi otroka, medtem ko je bil živ, toda ko je bil otrok mrtev, si vstal in jedel kruh.«',
        22: 'Rekel je: »Medtem ko je bil otrok še živ, sem se postil in jokal, kajti rekel sem: ›Kdo lahko pove, ali mi bo Bog milostljiv, da bo otrok lahko živel?‹',
        23: 'Toda sedaj je mrtev, zakaj bi se torej postil? Ali ga lahko ponovno privedem nazaj? Jaz bom šel k njemu, toda on se ne bo vrnil k meni.«',
        24: 'David je potolažil svojo ženo Batšébo in šel noter k njej in ležal z njo in rodila je sina in njegovo ime je imenoval Salomon. In Gospod ga je ljubil.',
        25: 'In poslal je po roki preroka Natána in ta je njegovo ime imenoval Jedidjá, zaradi Gospoda.',
        26: 'Joáb se je boril zoper Rabo Amónovih sinov in zavzel kraljevo mesto.',
        27: 'Joáb je poslal poslance k Davidu in rekel: »Boril sem se zoper Rabo in zavzel mesto vodá.',
        28: 'Zdaj torej zberi skupaj preostanek ljudstva in se utabôri zoper mesto in ga zavzemi, da ne bi jaz zavzel mesta in bi se ta imenoval po mojem imenu.«',
        29: 'In David je vse ljudstvo zbral skupaj in odšel v Rabo in se bojeval zoper njo ter jo zavzel.',
        30: 'Vzel je krono njihovega kralja iz njegove glave, katere teža je bila talent zlata z dragocenimi kamni in ta je bila postavljena na Davidovo glavo. In iz mesta je prinesel plena v velikem obilju.',
        31: 'Privedel je ljudstvo, ki je bilo tam in jih postavil pod žage, pod brane iz železa, pod sekire iz železa in jih primoral, da gredo skozi opekarsko peč. Tako je storil vsem mestom Amónovih otrok. Tako se je David in vse ljudstvo vrnilo v Jeruzalem.',
    },
    13: {
        1: 'Pripetilo se je po tem, da je Davidov sin Absalom imel lepo sestro, ki ji je bilo ime Tamara in Davidov sin Amnón, jo je vzljubil.',
        2: 'Amnón je bil tako obupan, da je zaradi svoje sestre Tamare zbolel, kajti bila je devica in Amnón si je mislil, da je zanj težko, da ji stori kakršno koli stvar.',
        3: 'Toda Amnón je imel prijatelja, katerega ime je bilo Jonadáb, sin Šimája, Davidovega brata. Jonadáb pa je bil zelo premeten človek.',
        4: 'Ta mu je rekel: »Zakaj si ti, ki si kraljev sin, iz dneva v dan slabotnejši? Ali mi ne boš povedal?« Amnón mu je rekel: »Ljubim Tamaro, sestro svojega brata Absaloma.«',
        5: 'Jonadáb mu je rekel: »Ulezi se na svojo posteljo in se naredi bolnega in ko pride tvoj oče, da te pogleda, mu reci: ›Prosim te, naj pride moja sestra Tamara in mi da jesti in pripravi hrano v mojem pogledu, da bom to lahko videl in to pojedel pri njeni roki.‹«',
        6: 'Tako se je Amnón ulegel in se naredil bolnega in ko je kralj prišel, da ga pogleda, je Amnón rekel kralju: »Prosim te, naj pride moja sestra Tamara in mi pripravi nekaj kolačev v mojem pogledu, da bom lahko jedel pri njeni roki.«',
        7: 'Potem je David poslal domov k Tamari, rekoč: »Pojdi sedaj k hiši svojega brata Amnóna in mu pripravi hrano.«',
        8: 'Tako je Tamara odšla k hiši svojega brata Amnóna in ta je ležal. Vzela je moko in jo zgnetla in naredila kolače v njegovem pogledu in kolače spekla.',
        9: 'Vzela je ponev in jih iztresla pred njim, toda odklonil je jesti. Amnón je rekel: »Odstranite od mene vse može.« In vsi možje so odšli od njega.',
        10: 'Amnón je rekel Tamari: »Prinesi hrano v sobo, da bom lahko jedel iz tvoje roke.« Tamara je vzela kolače, ki jih je naredila in jih prinesla v sobo k svojemu bratu Amnónu.',
        11: 'Ko jih je prinesla k njemu, da jé, jo je prijel in ji rekel: »Pridi, lezi z menoj, moja sestra.«',
        12: 'Odgovorila mu je: »Ne, moj brat, ne sili me, kajti nobena takšna stvar se ne bi smela storiti v Izraelu. Ne stôri te neumnosti.',
        13: 'In jaz, kam naj grem s svojo sramoto? Kar pa se tebe tiče, boš kakor nekdo izmed bedakov v Izraelu. Sedaj torej, prosim te, spregovori kralju, kajti on me ne bo zadržal pred teboj.«',
        14: 'Vendar ni hotel prisluhniti njenemu glasu, temveč ker je bil močnejši kakor ona, jo je prisilil in ležal z njo.',
        15: 'Potem jo je Amnón skrajno zasovražil, tako da je bilo sovraštvo, s katerim jo je zasovražil, večje kakor ljubezen, s katero jo je ljubil. In Amnón ji je rekel: »Vstani, izgini.«',
        16: 'Rekla mu je: »Ni razloga. To zlo, da me pošiljaš proč, je večje kakor drugo, ki si mi ga storil.« Toda ni ji hotel prisluhniti.',
        17: 'Potem je poklical svojega služabnika, ki mu je služil in rekel: »Postavi sedaj to žensko stran od mene in zapahni vrata za njo.«',
        18: 'Na sebi je imela obleko iz številnih barv, kajti s takšnim svečanim oblačilom so bile oblečene kraljeve hčere, ki so bile device. Potem jo je njegov služabnik odvedel ven in za njo zapahnil vrata.',
        19: 'Tamara pa si je na svojo glavo dala pepel in pretrgala obleko iz številnih barv, ki je bila na njej in svojo roko položila na svojo glavo ter jokajoč odšla.',
        20: 'Njen brat Absalom ji je rekel: »Ali je bil tvoj brat Amnón s teboj? Toda sedaj molči, moja sestra. On je tvoj brat. Ne oziraj se na to stvar.« Tako je Tamara ostala zapuščena v hiši svojega brata Absaloma.',
        21: 'Toda ko je kralj David slišal o vseh teh stvareh, je bil zelo ogorčen.',
        22: 'Absalom ni spregovoril svojemu bratu Amnónu niti dobro niti slabo, kajti Absalom je sovražil Amnóna, ker je posilil njegovo sestro Tamaro.',
        23: 'Pripetilo se je po dveh polnih letih, da je imel Absalom strižce ovc v Báal Hacórju, ki je poleg Efrájima in Absalom je povabil vse kraljeve sinove.',
        24: 'Absalom je prišel h kralju ter rekel: »Glej torej, tvoj služabnik ima strižce ovc, naj kralj, rotim te in njegovi služabniki gredo s tvojim služabnikom.«',
        25: 'Kralj je rekel Absalomu: »Ne, moj sin, naj ne gremo sedaj vsi, da ti ne bi bili v breme.« Silil ga je, vendar ni želel iti, temveč ga je blagoslovil.',
        26: 'Potem je Absalom rekel: »Če ne, prosim te, naj gre z nami moj brat Amnón.« Kralj mu je rekel: »Čemu bi on šel s teboj?«',
        27: 'Toda Absalom ga je silil, da je pustil Amnóna in vse kraljeve sinove iti z njim.',
        28: 'Torej Absalom je svojim služabnikom ukazal, rekoč: »Zapomnite si torej kdaj bo Amnónovo srce veselo z vinom in ko vam rečem: ›Udarite Amnóna;‹ tedaj ga ubijte, ne bojte se; ali vam nisem jaz ukazal? Bodite pogumni in bodite hrabri.«',
        29: 'Absalomovi služabniki so storili Amnónu, kakor je Absalom zapovedal. Potem so vsi kraljevi sinovi vstali in vsak mož se je povzpel na svojo mulo ter pobegnil.',
        30: 'Pripetilo se je, ko so bili na poti, da so prišle k Davidu novice, rekoč: »Absalom je umoril vse kraljeve sinove in niti eden izmed njih ni preostal.«',
        31: 'Potem je kralj vstal in raztrgal svoje obleke in legel na zemljo in vsi njegovi služabniki so stali poleg s svojimi pretrganimi oblačili.',
        32: 'Jonadáb, sin Davidovega brata Šimája, je odgovoril ter rekel: »Naj moj gospod ne domneva, da so umorili vse mladeniče, kraljeve sinove, kajti samo Amnón je mrtev, kajti z Absalomovo določitvijo je bilo to določeno od dneva, ko je posilil njegovo sestro Tamaro.',
        33: 'Zdaj torej naj si moj gospod kralj te stvari ne vzame k srcu, da misli, da so vsi kraljevi sinovi mrtvi, kajti samo Amnón je mrtev.«',
        34: 'Toda Absalom je pobegnil. In mladenič, ki je bil na straži, je povzdignil svoje oči in pogledal in glej, precej ljudi je prihajajo po poti od pobočja hriba za njim.',
        35: 'Jonadáb je rekel kralju: »Glej, kraljevi sinovi prihajajo. Kakor je tvoj služabnik rekel, tako je.«',
        36: 'Pripetilo se je, takoj ko je končal govorjenje, glej, da so prišli kraljevi sinovi in povzdignili svoj glas ter zajokali in tudi kralj in vsi njegovi služabniki so zelo bridko jokali.',
        37: 'Toda Absalom je pobegnil in odšel k Talmáju, Amihúdovemu sinu, kralju v Gešurju. David pa je vsak dan žaloval za svojim sinom.',
        38: 'Tako je Absalom pobegnil in odšel v Gešur in tam je bil tri leta.',
        39: 'Duša kralja Davida pa je hrepenela, da gre k Absalomu, kajti potolažen je bil glede Amnóna, glede na to, da je bil on mrtev.',
    },
    14: {
        1: 'Torej Cerújin sin Joáb je zaznal, da je bilo kraljevo srce [nagnjeno] k Absalomu.',
        2: 'Joáb je poslal v Tekóo in od tam privedel modro žensko ter ji rekel: »Prosim te, hlini se, da si žalovalka in sedaj si nadeni žalovalno obleko in se ne mazili z oljem, temveč bodi kakor ženska, ki je dolgo časa žalovala za mrtvim',
        3: 'in pojdi h kralju in mu govori na ta način.« Tako je Joáb položil besede v njena usta.',
        4: 'Ko je ženska iz Tekóe govorila kralju, je padla na svoj obraz do tal in se globoko priklonila ter rekla: »Pomagaj, oh kralj.«',
        5: 'Kralj ji je rekel: »Kaj te pesti?« Odgovorila je: »Res sem vdova in moj soprog je mrtev.',
        6: 'Tvoja pomočnica je imela dva sinova in skupaj sta se prepirala na polju in tam ni bilo nobenega, da ju loči, temveč je eden udaril drugega in ga usmrtil.',
        7: 'Glej, celotna družina je vstala zoper tvojo pomočnico in rekli so: ›Izroči tega, ki je usmrtil svojega brata, da ga bomo lahko ubili za življenje njegovega brata, ki ga je usmrtil in tudi dediča bomo uničili.‹ Tako bodo pogasili moj ogorek, ki je ostal in mojemu soprogu ne bodo pustili niti imena niti ostanka na tej zemlji.«',
        8: 'Kralj je rekel ženski: »Pojdi k svoji hiši in glede tebe dal bom zadolžitev.«',
        9: 'Ženska iz Tekóe je rekla kralju: »Moj gospod, oh kralj, krivičnost bodi na meni in na hiši mojega očeta, kralj in njegov prestol pa naj bosta brez krivde.«',
        10: 'Kralj je rekel: »Kdorkoli ti karkoli reče, ga privedi k meni in ne bo se te več dotaknil.«',
        11: 'Potem je rekla: »Prosim te, naj se kralj spomni Gospoda, svojega Boga, da ti nočeš trpeti, da krvni maščevalci še naprej uničujejo, da ne bi uničili mojega sina.« Rekel je: »Kakor Gospod živi niti en las tvojega sina ne bo padel k zemlji.«',
        12: 'Potem je ženska rekla: »Naj tvoja pomočnica, prosim te, spregovori eno besedo mojemu gospodu kralju.« In ta je rekel: »Povej.«',
        13: 'Ženska je rekla: »Zakaj si potem mislil storiti takšno stvar zoper Božje ljudstvo? Kajti kralj govori to stvar kakor nekdo, ki je pomanjkljiv, v tem, da kralj ne privede ponovno domov svojega pregnanega.',
        14: 'Kajti mi moramo umreti in smo kakor voda, razlita na tla, ki ne more biti ponovno zbrana niti Bog ne upošteva nobene osebe, vendar snuje način, da njegov pregnani ne bo izključen od njega.',
        15: 'Zdaj torej, ko sem prišla, da o tej stvari govorim mojemu gospodu kralju, je to zato, ker me je ljudstvo prestrašilo. Tvoja pomočnica je rekla: ›Spregovorila bom torej kralju. Lahko se zgodi, da bo kralj izpolnil zahtevo svoje pomočnice.‹',
        16: 'Kajti kralj bo slišal, da svojo pomočnico osvobodi iz roke človeka, ki hoče skupaj uničiti tako mene in mojega sina iz Božje dediščine.',
        17: 'Potem je tvoja pomočnica rekla Gospodu: ›Beseda mojega gospoda kralja bo sedaj tolažilna, kajti kakor angel od Boga, tako je moj gospod kralj, da razlikuje dobro in slabo, zato bo Gospod, tvoj Bog, s teboj.‹«',
        18: 'Potem je kralj ženski odgovoril in rekel: »Ne skrivaj pred menoj, prosim te, stvari, ki jo bom vprašal.« Ženska je rekla: »Naj moj gospod kralj sedaj spregovori.«',
        19: 'Kralj je rekel: » Mar ni v vsem tem s teboj Joábova roka?« Ženska je odgovorila ter rekla: » Kakor živi tvoja duša, moj gospod kralj, nihče se ne more izogniti ne na desno ne na levo od tega, kar je moj gospod kralj govoril, kajti tvoj služabnik Joáb mi je zaukazal in on je položil vse te besede v usta tvoje pomočnice,',
        20: 'da privleče na dan to obliko govora, je tvoj služabnik Joáb storil to stvar. In moj gospod je moder, glede na modrost Božjega angela, da ve vse stvari, ki so na zemlji.«',
        21: 'Kralj je rekel Joábu: »Glej torej, jaz sem storil to stvar, zato pojdi, ponovno privedi mladeniča Absaloma.«',
        22: 'Joáb je padel k tlom, na svoj obraz, se upognil in zahvalil kralju in Joáb je rekel: »Danes tvoj služabnik vé, da sem našel milost v tvojem pogledu, moj gospod, oh kralj, v tem, da je kralj izpolnil zahtevo svojega služabnika.«',
        23: 'Tako je Joáb vstal in odšel v Gešur in Absaloma privedel v Jeruzalem.',
        24: 'Kralj je rekel: »Naj se obrne k svoji lastni hiši in naj ne vidi mojega obraza.« Tako se je Absalom vrnil k svoji lastni hiši in ni videl kraljevega obraza.',
        25: 'Toda v vsem Izraelu ni bilo nikogar, da bi bil tako zelo hvaljen zaradi svoje lepote kakor Absalom. Od podplata svojega stopala, celo do krone njegove glave, ni bilo na njem nobenega madeža.',
        26: 'In ko je ostrigel svojo glavo (kajti ob koncu vsakega leta si jo je ostrigel, ker so bili lasje na njem težki, zato jo je ostrigel) si je stehtal lase svoje glave, dvesto šeklov po kraljevi teži.',
        27: 'Absalomu so se tam rodili trije sinovi in ena hči, ki ji je bilo ime Tamara. Bila je ženska lepega obličja.',
        28: 'Tako je Absalom dve polni leti prebival v Jeruzalemu in ni videl kraljevega obraza.',
        29: 'Zato je Absalom poslal po Joába, da ga pošlje h kralju, toda ta ni hotel priti k njemu in ko je drugič ponovno poslal, ta ni hotel priti.',
        30: 'Zato je rekel svojim služabnikom: »Glejte, Joábovo polje je v bližini mojega in tam ima ječmen. Pojdite in ga požgite.« In Absalomovi služabniki so zažgali polje.',
        31: 'Potem je Joáb vstal in prišel k Absalomu v njegovo hišo ter mu rekel: »Zakaj so tvoji služabniki zažgali moje polje?«',
        32: 'Absalom je odgovoril Joábu: »Glej, poslal sem k tebi, rekoč: ›Pridi sèm, da te lahko pošljem h kralju, da rečem: ›Zakaj sem prišel iz Gešurja?‹‹ Zame bi bilo dobro, da bi bil še vedno tam. Sedaj mi torej pusti videti kraljev obraz in če bo kakršnakoli krivičnost v meni, naj me ubije.«',
        33: 'Tako je Joáb prišel h kralju in mu povedal in ko je dal poklicati Absaloma, je ta prišel h kralju in se pred kraljem priklonil na svoj obraz do tal in kralj je poljubil Absaloma.',
    },
    15: {
        1: 'Pripetilo se je po tem, da si je Absalom pripravil vozove, konje in petdeset mož, da so tekli pred njim.',
        2: 'Absalom je vstajal zgodaj in stal poleg poti velikih vrat in to je bilo tako, da ko je katerikoli človek imel polemiko, je prišel h kralju za sodbo, potem mu je Absalom zaklical in rekel: »Iz katerega mesta si?« In ta je rekel: »Tvoj služabnik je iz enega izmed Izraelovih rodov.«',
        3: 'Absalom mu je rekel: »Poglej, tvoje zadeve so dobre in pravilne; toda tam ni nobenega človeka, poslanega od kralja, da te sliši.«',
        4: 'Poleg tega je Absalom rekel: »Oh da bi mene postavili za sodnika v deželi, da bi vsak človek, ki ima kakršnokoli tožbo ali zadevo, lahko prišel k meni in bi mu jaz storil pravico!«',
        5: 'In to je bilo tako, da ko je katerikoli moški prišel blizu k njemu, da se mu globoko prikloni, je svojo roko iztegnil naprej, ga prijel in ga poljubil.',
        6: 'Na ta način je Absalom počel vsemu Izraelu, ki so hodili h kralju po sodbo. Tako je Absalom kradel srca Izraelovih mož.',
        7: 'Pripetilo se je po štiridesetih letih, da je Absalom rekel kralju: »Prosim te, naj grem in izpolnim svojo zaobljubo, ki sem jo zaobljubil Gospodu v Hebrónu.',
        8: 'Kajti tvoj služabnik se je zaobljubil, medtem ko je prebival pri Gešurju v Siriji, rekoč: ›Če me bo Gospod zares ponovno privedel v Jeruzalem, potem bom služil Gospodu.‹«',
        9: 'Kralj mu je rekel: »Pojdi v miru.« Tako je vstal in odšel v Hebrón.',
        10: 'Toda Absalom je poslal oglednike po vseh Izraelovih rodovih, rekoč: »Takoj ko zaslišite zvok šofarja, potem boste rekli: ›Absalom kraljuje v Hebrónu.‹«',
        11: 'Z Absalomom je iz Jeruzalema odšlo dvesto mož, ki so bili poklicani. Odšli pa so v svoji toposti in niso vedeli nobene stvari.',
        12: 'Absalom je poslal po Gilčana Ahitófela, Davidovega svetovalca, iz njegovega mesta, torej iz Gila, medtem ko je daroval klavne daritve. In zarota je bila močna, kajti ljudstvo je nenehno naraščalo z Absalomom.',
        13: 'K Davidu je prišel poslanec, rekoč: »Srca Izraelovih mož sledijo Absalomu.«',
        14: 'David je rekel vsem svojim služabnikom, ki so bili z njim pri Jeruzalemu: »Vstanimo in pobegnimo, kajti sicer ne bomo pobegnili pred Absalomom. Pohitimo, da nas ne bi nenadoma dohitel in nad nas privedel zla in mesto udaril z ostrino meča.«',
        15: 'Kraljevi služabniki so rekli kralju: »Glej, tvoji služabniki so pripravljeni storiti, karkoli bo moj gospod kralj določil.«',
        16: 'Kralj je odšel naprej in vsa njegova družina za njim. Kralj pa je pustil deset žensk, ki so bile priležnice, da varujejo hišo.',
        17: 'Kralj je odšel naprej in vse ljudstvo za njim in se mudil na kraju, ki je bil daleč proč.',
        18: 'Vsi njegovi služabniki so šli poleg njega in vsi Keretéjci in vsi Péletovci in vsi Gitéjci, šeststo mož, ki so prišli za njim iz Gata, so prečkali pred kraljem.',
        19: 'Potem je kralj rekel Gitéjcu Itáju: »Čemu greš tudi ti z nami? Vrni se na svoj kraj in prebivaj s kraljem, kajti tujec si in tudi izgnanec.',
        20: 'Glede na to, da si prišel šele včeraj, ali naj te ta dan pripravim hoditi z nami gor in dol? Ker grem, kamor lahko, se vrni in svoje brate vzemi nazaj. Usmiljenje in resnica naj bosta s teboj.«',
        21: 'Itáj je odgovoril kralju in rekel: » Kakor živi Gospod in kakor živi moj gospod kralj, zagotovo, na kateremkoli kraju bo moj gospod kralj, bodisi v smrti ali življenju, celo tam bo tudi tvoj služabnik.«',
        22: 'David je rekel Itáju: »Pojdi in prečkaj.« Gitéjec Itáj je šel čez in vsi njegovi možje in vsi malčki, ki so bili z njim.',
        23: 'In vsa dežela je jokala z močnim glasom in vse ljudstvo je šlo čez. Tudi sam kralj je šel čez potok Kidron in vse ljudstvo je šlo čez, proti poti divjine.',
        24: 'Glej, tudi Cadók in vsi Lévijevci so bili z njim, nesoč skrinjo Božje zaveze in odložili so Božjo skrinjo. Abjatár je odšel gor, dokler ni vse ljudstvo šlo iz mesta.',
        25: 'Kralj je Cadóku rekel: »Božjo skrinjo odnesite nazaj v mesto. Če bom našel naklonjenost v Gospodovih očeh, me bo ponovno privedel in mi pokazal oboje, to in njeno prebivališče,',
        26: 'toda če reče tako: ›Nimam veselja v tebi;‹ glej, tukaj sem, naj mi stori, kakor se mu zdi dobro.«',
        27: 'Kralj je tudi rekel duhovniku Cadóku: » Mar nisi ti videc? V miru se vrni v mesto in tvoja dva sinova s teboj, tvoj sin Ahimáac in Jonatan, Abjatárjev sin.',
        28: 'Glejte, mudil se bom na ravnini divjine, dokler ne bo prišla od vas beseda, da me potrdite.«',
        29: 'Torej Cadók in Abjatár sta Božjo skrinjo ponovno odnesla v Jeruzalem in ostala sta tam.',
        30: 'David je odšel gor po pobočju Oljske gore in jokal, ko se je vzpenjal in svojo glavo je imel pokrito in hodil je bos. Vse ljudstvo, ki je bilo z njim, je vsak pokril svojo glavo in hodili so gor in jokali, medtem ko so hodili gor.',
        31: 'In nekdo je povedal Davidu, rekoč: »Ahitófel je z Absalomom med zarotniki.« David je rekel: »Oh Gospod, prosim te, obrni Ahitófelov nasvet v norost.«',
        32: 'Pripetilo se je, da ko je David prišel na vrh gore, kjer je oboževal Boga, glej, je prišel Arkéjec Hušáj, da ga sreča, s svojim pretrganim plaščem in zemljo na svoji glavi,',
        33: 'ki mu je David rekel: »Če greš z menoj naprej, potem mi boš v breme,',
        34: 'toda če se vrneš k mestu in rečeš Absalomu: ›Jaz bom tvoj služabnik, oh kralj, kakor sem bil doslej služabnik tvojega očeta, tako bom sedaj tudi tvoj služabnik,‹ potem boš lahko zame premagal Ahitófelov nasvet.',
        35: 'In ali nisi tam z duhovnikoma Cadókom in Abjatárjem? Zato naj bo, da kakršnokoli stvar boš slišal iz kraljeve hiše, boš to povedal duhovnikoma Cadóku in Abjatárju.',
        36: 'Glej, onadva imata tam s seboj svoja dva sinova, Cadókovega sina Ahimáaca in Abjatárjevega sina Jonatana. Po njima boste poslali k meni vsako stvar, ki jo lahko slišite.«',
        37: 'Tako je Davidov prijatelj Hušáj prišel v mesto in Absalom je prišel v Jeruzalem.',
    },
    16: {
        1: 'Ko je David ravno prešel vrh hriba, glej, ga je srečal Mefibóšetov služabnik Cibá, s parom osedlanih oslov in na njih dvesto hlebov kruha, sto grozdov rozin, sto poletnih sadov in vinski meh.',
        2: 'Kralj je rekel Cibáju: »Kaj nameravaš s tem?« Cibá je rekel: »Ti osli so za kraljevo družino, da jaha na njih. Kruh in poletno sadje za mladeniče, da jedo, in vino, da tisti, ki so v divjini oslabeli, lahko pijejo.«',
        3: 'Kralj je rekel: »In kje je sin tvojega gospodarja?« Cibá je rekel kralju: »Glej, on ostaja v Jeruzalemu, kajti rekel je: ›Danes mi bo Izraelova hiša obnovila kraljestvo mojega očeta.‹«',
        4: 'Potem je kralj rekel Cibáju: »Glej, tvoje je vse, kar pripada Mefibóšetu.« Cibá je rekel: »Ponižno te rotim, da lahko najdem milost v tvojem pogledu, moj gospod, oh kralj.«',
        5: 'Ko je kralj David prišel v Bahurím, glej, je od tam prišel mož iz družine Savlove hiše, katerega ime je bilo Šimí, Gerájev sin. Prišel je naprej in nenehno preklinjal, medtem ko je prihajal.',
        6: 'V Davida in v vse služabnike kralja Davida je lučal kamne in vse ljudstvo in vsi mogočni možje so bili na njegovi desni roki in na njegovi levi.',
        7: 'Tako je govoril Šimí, ko je preklinjal: »Pridi ven, pridi ven, ti, krvoločen človek in ti, Beliálov človek.',
        8: 'Gospod je povrnil nad teboj vso kri Savlove hiše, namesto katerega si zakraljeval in Gospod je kraljestvo izročil v roko tvojega sina Absaloma. Glej, ujet si v svoji vragoliji, ker si krvoločen človek.«',
        9: 'Potem je Cerújin sin Abišáj rekel kralju: »Zakaj bi ta mrtvi pes preklinjal mojega gospoda kralja? Naj grem preko, prosim te in snamem njegovo glavo.«',
        10: 'Kralj pa je rekel: »Kaj imam z vama, Cerújina sinova? Tako naj preklinja, ker mu je Gospod rekel: ›Preklinjaj Davida.‹ Kdo bo potem rekel: ›Čemu si tako storil?‹«',
        11: 'David je rekel Abišáju in vsem svojim služabnikom: »Glejte, moj sin, ki je prišel iz moje notranjosti, mi streže po življenju. Kako mnogo bolj lahko sedaj to stori ta Benjaminovec? Pustite ga na miru in naj preklinja, kajti Gospod mu je zaukazal.',
        12: 'Morda bo Gospod pogledal na mojo stisko in da mi bo Gospod poplačal dobro za njegovo preklinjanje ta dan.«',
        13: 'Medtem ko so David in njegovi možje šli po poti, je Šimí hodil vzdolž, na drugi strani hriba, nasproti njemu in preklinjal, medtem ko je hodil in lučal kamne vanj in metal prah.',
        14: 'Kralj in vse ljudstvo, ki so bili z njim, so prišli izmučeni in se tam osvežili.',
        15: 'Absalom in vse ljudstvo Izraelovih mož pa so prišli v Jeruzalem in Ahitófel z njim.',
        16: 'Pripetilo se je, ko je Davidov prijatelj Arkéjec Hušáj prišel k Absalomu, da je Hušáj rekel Absalomu: »Živel kralj, živel kralj.«',
        17: 'Absalom je rekel Hušáju: » Ali je to tvoja prijaznost do tvojega prijatelja? Zakaj nisi šel s svojim prijateljem?«',
        18: 'Hušáj je rekel Absalomu: »Ne, temveč katerega Gospod in to ljudstvo in vsi Izraelovi možje izberejo, njegov bom in z njim bom ostal.',
        19: 'In ponovno, komu naj bi služil? Ali naj ne bi služil v prisotnosti njegovega sina? Kakor sem služil v prisotnosti tvojega očeta, tako bom v tvoji prisotnosti.«',
        20: 'Potem je Absalom rekel Ahitófelu: »Dajte nasvet med vami, kaj naj storimo.«',
        21: 'Ahitófel je rekel Absalomu: »Pojdi noter v priležnice svojega očeta, ki jih je pustil, da varujejo hišo in ves Izrael bo slišal, da si preziran od svojega očeta. Potem bodo močne roke vseh, ki so s teboj.«',
        22: 'Tako so Absalomu razprostrli šotor na vrhu hiše in Absalom je šel v priležnice svojega očeta pred očmi vsega Izraela.',
        23: 'Nasvet Ahitófela, ki je v tistih dneh svetoval, je bil, kakor če bi človek poizvedoval pri Božjem oraklju, tako so bili vsi Ahitófelovi nasveti tako z Davidom kakor z Absalomom.',
    },
    17: {
        1: 'Poleg tega je Ahitófel rekel Absalomu. »Naj sedaj izberem dvanajst tisoč mož in vstal bom in to noč zasledoval Davida',
        2: 'in prišel bom nadenj, medtem ko je izmučen in slabotnih rok in ga prestrašil. Vse ljudstvo, ki je z njim, bo pobegnilo, udaril pa bom samo kralja',
        3: 'in vse ljudstvo bom privedel nazaj k tebi. Mož, ki ga iščeš, je kakor, če se vsi vrnejo; tako bo vse ljudstvo v miru.«',
        4: 'Beseda je dobro ugajala Absalomu in vsem Izraelovim starešinam.',
        5: 'Potem je Absalom rekel: »Pokličite sedaj tudi Arkéjca Hušája in naj slišimo tudi, kaj pravi on.«',
        6: 'Ko je Hušáj prišel k Absalomu, mu je Absalom spregovoril, rekoč: »Ahitófel je govoril na ta način. Ali naj storimo po njegovem govoru? Če ne, ti spregovori.«',
        7: 'Hušáj je rekel Absalomu: »Nasvet, ki ti ga je tokrat dal Ahitófel, ni dober.',
        8: 'Kajti,« je rekel Hušáj, »poznaš svojega očeta in njegove može, da so mogočni možje in v svojih mislih komaj čakajo, kakor medvedka, oropana svojih mladičev, na polju. In tvoj oče je bojevnik in ne bo prenočeval z ljudstvom.',
        9: 'Glej, sedaj je skrit v neki jami ali na nekem drugem kraju. In zgodilo se bo, ko bodo na začetku nekateri izmed njih premagani, da kdorkoli to sliši, bo rekel: ›Tam je pokol med ljudstvom, ki sledijo Absalomu.‹',
        10: 'Tudi tisti, ki je hraber, katerega srce je kakor srce leva, se bo popolnoma stopil, kajti ves Izrael ve, da je tvoj oče mogočen človek in tisti, ki so z njim, so hrabri možje.',
        11: 'Zato svetujem, da se ves Izrael nasploh zbere k tebi, od Dana, celo do Beeršébe, kakor je peska, ki je pri morju zaradi množice in da greš ti osebno v bitko.',
        12: 'Tako bomo prišli nadenj na nekem kraju, kjer bo najden in posvetili bomo nanj, kakor rosa pada na tla in od njega in od vseh mož, ki so z njim, tam ne bo nihče ostal.',
        13: 'Poleg tega, če bo odšel v mesto, potem bo ves Izrael do tega mesta prinesel vrvi in potegnili ga bomo v reko, dokler ne bo tam najden niti en majhen kamen.«',
        14: 'Absalom in vsi možje iz Izraela so rekli: »Nasvet Arkéjca Hušája je boljši kakor nasvet Ahitófela.« Kajti Gospod je določil, da porazi dober Ahitófelov nasvet, z namenom, da bo Gospod lahko privedel zlo nad Absaloma.',
        15: 'Potem je Hušáj rekel Cadóku in duhovniku Abjatárju: »Tako in tako je Ahitófel svetoval Absalomu in starešinam Izraela, in tako in tako sem svetoval jaz.',
        16: 'Zdaj torej hitro pošlji in povej Davidu, rekoč: ›To noč ne prenočuj na ravninah divjine, temveč naglo prečkaj, da te ne bi kralj požrl in vse ljudstvo, ki je z njim.‹«',
        17: 'Torej Jonatan in Ahimáac sta ostala v En Rogelu, kajti nista smela biti videna, da pridete v mesto. In deklina je odšla in jima povedala. Odšla sta ter povedala kralju Davidu.',
        18: 'Kljub temu ju je videl deček in povedal Absalomu. Toda oba izmed njiju sta hitro odšla proč in prišla k hiši človeka v Bahurímu, ki je na svojem dvorišču imela vodnjak, kamor sta se spustila.',
        19: 'Ženska je vzela [pokrivalo] in pokrivalo razprostrla čez ustje vodnjaka in nanj raztresla zmleto žito in stvar ni bila znana.',
        20: 'Ko so Absalomovi služabniki prišli v hišo k ženski, so rekli: »Kje sta Ahimáac in Jonatan?« Ženska jim je rekla: »Odšla sta čez vodni potok.« Ko pa so ju iskali in ju niso mogli najti, so se vrnili v Jeruzalem.',
        21: 'Pripetilo se je, potem ko so odšli, da sta prišla ven iz vodnjaka in odšla in kralju Davidu povedala in Davidu rekla: »Vstani in hitro prečkaj vodo, kajti Ahitófel je tako svetoval zoper tebe.«',
        22: 'Potem je David vstal in vse ljudstvo, ki je bilo z njim in so prečkali Jordan. Do jutranje svetlobe ni manjkal niti eden izmed teh, ki so prečkali Jordan.',
        23: 'Ko je Ahitófel videl, da njegov nasvet ni bil sleden, je osedlal svojega osla, vstal in se spravil domov k svoji hiši, k svojemu mestu in svojo družino postavil v red in samega sebe obesil in umrl in bil pokopan v mavzoleju svojega očeta.',
        24: 'Potem je David prišel v Mahanájim. Absalom pa je prečkal Jordan, on in vsi možje iz Izraela z njim.',
        25: 'Absalom je namesto Joába za poveljnika vojske postavil Amasája. Ta Amasá je bil sin moža, katerega ime je bilo Itra, Izraelec, ki je odšel noter k Naháševi hčeri Abigájili, sestri Joábove matere Cerúje.',
        26: 'Tako so Izrael in Absalom taborili v deželi Gileád.',
        27: 'Pripetilo se je, ko je David prišel v Mahanájim, da so Nahášev sin Šobí, iz Rabe Amónovih otrok in Amiélov sin Mahír iz Lo Dabárja in Gileádec Barziláj iz Roglíma',
        28: 'prinesli postelje, umivalnike, lončene posode ter pšenico, ječmen, moko, praženo zrnje, fižol, lečo, posušene stročnice,',
        29: 'med, maslo, ovce in kravji sir za Davida in za ljudstvo, ki je bilo z njim, da jedo, kajti rekli so: »Ljudstvo je lačno, izmučeno in žejno v divjini.«',
    },
    18: {
        1: 'David je preštel ljudstvo, ki je bilo z njim in nadnje postavil poveljnike nad tisočimi in poveljnike nad stotimi.',
        2: 'David je poslal naprej tretjino izmed ljudstva pod Joábovo roko in tretjino pod roko Abišája, Cerújinega sina, Joábovega brata in tretjino pod roko Gitéjca Itája. Kralj je rekel ljudstvu: »Tudi sam bom zagotovo šel z vami naprej.«',
        3: 'Toda ljudstvo je odgovorilo: »Ne boš šel naprej, kajti če mi pobegnemo, jim ne bo mar za nas. Niti, če nas polovica umre, jim ne bo mar za nas. Toda ti si sedaj vreden deset tisoč nas. Zato je sedaj bolje, da nas okrepiš iz mesta.«',
        4: 'Kralj jim je rekel: »Storil bom, kar se vam zdi najbolje.« Kralj je stal ob strani velikih vrat, vse ljudstvo pa je prišlo ven po stotih in po tisočih.',
        5: 'Kralj je zapovedal Joábu, Abišáju in Itáju, rekoč: »Zaradi mene nežno postopajte z mladeničem, torej z Absalomom.« Vse ljudstvo je slišalo, ko je kralj vsem poveljnikom dal zadolžitev glede Absaloma.',
        6: 'Tako je ljudstvo odšlo ven na polje zoper Izrael. In bitka je bila v Efrájimskem gozdu,',
        7: 'kjer je bilo izraelsko ljudstvo pobito pred Davidovimi služabniki in tam je bil ta dan velik pokol dvajsetih tisočev mož.',
        8: 'Kajti tam je bila bitka razpršena preko obličja vse dežele. In gozd je ta dan požrl več ljudstva, kakor jih je požrl meč.',
        9: 'Absalom je srečal Davidove služabnike. In Absalom je jahal na muli in mula je šla pod debelimi vejami velikega hrasta in njegova glava se je ujela v hrast in vzet je bil gor med nebo in zemljo. Mula, ki je bila pod njim, pa je odšla proč.',
        10: 'Nek mož je to videl in povedal Joábu ter rekel: »Glej, videl sem Absaloma, visečega na hrastu.«',
        11: 'Joáb je rekel možu, ki mu je povedal: »Glej, videl si ga in zakaj ga nisi tam udaril k tlom? In jaz bi ti dal deset šeklov srebra in pas.«',
        12: 'Mož je rekel Joábu: »Čeprav bi v svojo roko prejel tisoč šeklov srebra, vendar svoje roke ne bi iztegnil zoper kraljevega sina, kajti slišali smo, da je kralj zadolžil tebe, Abišája in Itája, rekoč: ›Pazite, da se nihče ne dotakne mladeniča Absaloma.‹',
        13: 'Sicer bi storil hinavstvo zoper svoje lastno življenje, kajti nobena stvar ni skrita pred kraljem in ti sam bi se postavil zoper mene.«',
        14: 'Potem je Joáb rekel: »Ne morem se tako muditi s teboj.« V svojo roko je vzel tri puščice in jih zabodel skozi Absalomovo srce, medtem ko je bil še živ v sredi hrasta.',
        15: 'Deset mladeničev, ki so nosili Joábovo bojno opremo, je obdalo Absaloma in ga usmrtilo.',
        16: 'Joáb je zatrobil s šofarjem in ljudstvo se je vrnilo od zasledovanja za Izraelom, kajti Joáb je zadržal ljudstvo.',
        17: 'Vzeli so Absaloma, ga vrgli v veliko jamo v gozdu in nanj položili zelo velik kup kamenja in ves Izrael je zbežal, vsak k svojemu šotoru.',
        18: '§ Torej Absalom si je [še] v svojem življenju vzel in si postavil steber, ki je v kraljevi dolini, kajti rekel je: »Nobenega sina nimam, da ohrani moje ime v spominu.« Steber je poimenoval po svojem lastnem imenu in tako se imenuje do današnjega dne, Absalomov kraj.',
        19: 'Potem je Cadókov sin Ahimáac rekel: »Naj sedaj stečem in kralju prinesem novice, kako se je Gospod maščeval nad njegovimi sovražniki.«',
        20: 'Joáb mu je rekel: »Danes ne boš nosil novic, temveč boš novice nosil drug dan. Toda danes ne boš nosil nobenih novic, ker je kraljev sin mrtev.«',
        21: 'Potem je Joáb rekel Kušíju: »Pojdi, povej kralju, kar si videl.« Kuší se je priklonil Joábu in stekel.',
        22: 'Potem je Cadókov sin Ahimáac ponovno rekel Joábu: »Toda kakorkoli, prosim te, naj tudi jaz prav tako stečem za Kušíjem.« Joáb pa je rekel: »Čemu bi tekel, moj sin, glede na to, da nimaš pripravljenih novic?«',
        23: '»Toda kakorkoli,« je rekel, »naj stečem.« Rekel mu je: »Steci.« Potem je Ahimáac stekel po poti ravnine in prehitel Kušíja.',
        24: 'David je sedel med dvemi velikimi vrati. Stražar pa je šel gor do strehe nad velikimi vrati k obzidju in povzdignil svoje oči in pogledal in glej, mož je tekel sam.',
        25: 'Stražar je zaklical in povedal kralju. Kralj je rekel: »Če je sam, so novice v njegovih ustih.« Hitro je prišel in se približal.',
        26: 'Stražar je zagledal teči drugega moža in stražar je zaklical vratarju ter rekel: »Glej, drug človek teče sam.« Kralj je rekel: »Tudi ta prinaša novice.«',
        27: 'Stražar je rekel: »Mislim, da je tek sprednjega podoben teku Cadókovega sina Ahimáaca.« Kralj je rekel: »Dober človek je in prihaja z dobrimi novicami.«',
        28: 'Ahimáac je zaklical in kralju rekel: »Vse je dobro.« S svojim obrazom je padel dol na zemljo pred kraljem in rekel: »Blagoslovljen bodi Gospod, tvoj Bog, ki je izročil ljudi, ki so svojo roko dvignili zoper mojega gospoda kralja.«',
        29: 'Kralj je rekel: »Ali je mladenič Absalom varen?« Ahimáac je odgovoril: »Ko je Joáb poslal kraljevega služabnika in mene, tvojega služabnika, sem videl velik hrup, toda nisem vedel, kaj je to bilo.«',
        30: 'Kralj mu je rekel: »Obrni se vstran in stoj tukaj.« Obrnil se je vstran in mirno stal.',
        31: 'In glej, prišel je Kuší. Kuší je rekel: »Novice, moj gospod kralj, kajti Gospod te je ta dan maščeval pred vsemi tistimi, ki so se vzdignili zoper tebe.«',
        32: 'Kralj je rekel Kušíju: »Je mladenič Absalom varen?« Kuší je odgovoril: »Sovražniki mojega gospoda kralja in vsi, ki se vzdignejo zoper tebe, da ti škodijo, naj bodo, kakor je ta mladenič.«',
        33: 'Kralj je bil zelo pretresen in odšel gor v sobo nad velikimi vrati in jokal. Medtem ko je šel, je tako govoril: »Oh moj sin Absalom, moj sin, moj sin Absalom! Da bi Bog dal, da bi jaz umrl zate, oh Absalom, moj sin, moj sin!«',
    },
    19: {
        1: 'To je bilo povedano Joábu: »Glej, kralj joka in žaluje za Absalomom.«',
        2: 'Zmaga tega dne je bila obrnjena v žalovanje vsemu ljudstvu, kajti ljudstvo je tisti dan slišalo govoriti, kako je bil kralj užaloščen zaradi svojega sina.',
        3: 'Ljudstvo se je tisti dan skrivoma spravilo v mesto, kakor se ljudstvo, ki je osramočeno, odplazi, ko v boju zbeži.',
        4: 'Toda kralj je pokril svoj obraz in kralj je jokal z močnim glasom: »Oh moj sin Absalom, oh Absalom, moj sin, moj sin!«',
        5: 'Joáb je prišel v hišo h kralju in rekel: »Ta dan si osramotil obraze vseh svojih služabnikov, ki so ta dan rešili tvoje življenje in življenja tvojih sinov in tvojih hčera in življenja tvojih soprog in življenja tvojih priležnic,',
        6: 'v tem, da ti ljubiš svoje sovražnike in sovražiš svoje prijatelje. Kajti ta dan si oznanil, da se ne oziraš niti na prince niti na služabnike, kajti ta dan zaznavam, da če bi Absalom živel in bi ta dan mi vsi umrli, potem bi ti to dobro ugajalo.',
        7: 'Zdaj torej vstani, pojdi naprej in tolažilno govori svojim služabnikom, kajti prisegam pri Gospodu, če ne greš naprej, to noč nobeden ne bo ostal s teboj in huje ti bo kakor vse zlo, ki te je zadelo od tvoje mladosti do sedaj.«',
        8: 'Potem je kralj vstal in se usedel pri velikih vratih. In vsemu ljudstvu so povedali, rekoč: »Glejte, kralj sedi pri velikih vratih.« Vse ljudstvo je prišlo pred kralja, kajti Izrael je zbežal vsak mož k svojemu šotoru.',
        9: 'Vse ljudstvo je bilo nesložno po vseh Izraelovih rodovih, rekoč: »Kralj nas je rešil iz roke naših sovražnikov in nas osvobodil iz roke Filistejcev; sedaj pa je zaradi Absaloma pobegnil iz dežele.',
        10: 'Absalom, ki smo ga mazilili nad seboj, je mrtev v bitki. Zdaj torej, zakaj ne spregovorite besedo o privedbi kralja nazaj?«',
        11: 'Kralj David je poslal k duhovnikoma Cadóku in Abjatárju, rekoč: »Govorita Judovim starešinam, rekoč: ›Zakaj ste zadnji, da bi privedli kralja nazaj v njegovo hišo, glede na to, da je govor vsega Izraela prišel do kralja, celó k njegovi hiši.',
        12: 'Vi ste moji bratje, vi ste moje kosti in moje meso. Zakaj ste potem zadnji, da kralja pripeljete nazaj?‹',
        13: 'In Amasáju recite: › Ali nisi ti od moje kosti in od mojega mesa? Bog naj mi tako stori in še več, če ne boš nenehno pred menoj poveljnik vojske na Joábovem položaju.‹«',
        14: 'In nagnil je srce vseh Judovih mož, celo kakor srce enega človeka, tako da so kralju poslali to besedo: »Vrni se ti in vsi tvoji služabniki.«',
        15: 'Tako se je kralj vrnil in prišel k Jordanu. In Juda je prišel v Gilgál, da gre, da sreča kralja, da spremi kralja čez Jordan.',
        16: 'In Šimí, Gerájev sin, Benjaminovec, ki je bil iz Bahuríma, je pohitel in prišel dol z Judovimi možmi, da sreča kralja Davida.',
        17: 'Tam je bilo z njim tisoč mož iz Benjamina in Cibá, služabnik Savlove hiše in njegovih petnajst sinov in njegovih dvajset služabnikov z njim in pred kraljem so šli čez Jordan.',
        18: 'Tam je šla čez rečna ladja, da prenese čez kraljevo družino in da stori, kar se mu je zdelo dobro. Gerájev sin Šimí pa je padel dol pred kraljem, ko je ta hotel iti čez Jordan',
        19: 'in kralju rekel: »Naj moj gospod krivičnosti ne pripiše meni niti se ne spominjaj tega, kar je tvoj služabnik sprevrženo storil tistega dne, ko je moj gospod kralj odšel iz Jeruzalema, da bi si to kralj vzel k srcu.',
        20: 'Kajti tvoj služabnik ve, da sem grešil. Glej, zato sem ta dan prvi prišel iz vse Jožefove hiše, da grem dol, da srečam svojega gospoda kralja.«',
        21: 'Toda Cerújin sin Abišáj je odgovoril in rekel: »Ali ne bo Šimí usmrčen zaradi tega, ker je preklinjal Gospodovega maziljenca?«',
        22: 'David pa je rekel: »Kaj imam z vama, vidva, Cerújina sinova, da bi mi bila ta dan nasprotnika? Ali naj bo ta dan kdorkoli usmrčen v Izraelu? Kajti ali ne vem, da sem ta dan kralj nad Izraelom?«',
        23: 'Zato je kralj rekel Šimíju: »Ne boš umrl.« In kralj mu je prisegel.',
        24: 'Savlov sin Mefibóšet je prišel dol, da sreča kralja in niti ni obul svojih stopal, niti ni postrigel svoje brade, niti ni umil svojih oblačil od dneva, ko je kralj odpotoval, do dneva, ko je ponovno prišel v miru.',
        25: 'Pripetilo se je, ko je prišel v Jeruzalem, da sreča kralja, da mu je kralj rekel: »Zakaj nisi šel z menoj, Mefibóšet?«',
        26: 'Ta je odgovoril: »Moj gospod, oh kralj, moj služabnik me je zavedel, kajti tvoj služabnik je rekel: ›Osedlal si bom osla, da bom lahko jahal na njem in šel h kralju, ker je tvoj služabnik hrom.‹',
        27: 'In ta je obrekoval tvojega služabnika mojemu gospodu kralju, toda moj gospod kralj je kakor angel od Boga. Stôri torej, kar je dobro v tvojih očeh.',
        28: 'Kajti vsi iz hiše mojega očeta so bili le kot mrtvi možje pred mojim gospodom kraljem, vendar si svojega služabnika postavil med tiste, ki so jedli pri tvoji lastni mizi. Kakšno pravico imam torej, da še kakorkoli kličem h kralju?«',
        29: 'Kralj mu je rekel: »Zakaj še govoriš o svojih zadevah? Rekel sem: ›Ti in Cibá si razdelita deželo.‹«',
        30: 'Mefibóšet je rekel kralju: »Da, naj on vzame vse, potem ko se je moj gospod kralj v miru ponovno vrnil v svojo lastno hišo.«',
        31: 'Gileádec Barziláj je prišel dol iz Roglíma in s kraljem odšel čez Jordan, da ga spremi čez Jordan.',
        32: 'Torej Barziláj je bil zelo ostarel mož, star celó osemdeset let. Kralju je priskrbel oskrbo, medtem ko je ta ležal pri Mahanájimu, kajti bil je zelo izjemen človek.',
        33: 'Kralj je rekel Barziláju: »Z menoj pridi čez in hranil te bom v Jeruzalemu.«',
        34: 'Barziláj pa je kralju rekel: »Doklej bom še živel, da bi s kraljem šel gor v Jeruzalem?',
        35: 'Ta dan sem star osemdeset let in ali lahko razločim med dobrim in zlom? Ali lahko tvoj služabnik okuša, kar jem ali kar pijem? Ali še lahko slišim glas prepevajočih mož in prepevajočih žensk? Zakaj bi bil torej tvoj služabnik še breme mojemu gospodu kralju?',
        36: 'Tvoj služabnik bo s kraljem šel krajšo pot čez Jordan. Zakaj bi me kralj poplačal s takšno nagrado?',
        37: 'Naj se tvoj služabnik, prosim te, obrne nazaj, da lahko umrem v svojem lastnem mestu in pokopan bom poleg groba svojega očeta in svoje matere. Toda poglej svojega služabnika Kimháma. Naj gre on preko z mojim gospodom kraljem in stôri mu, kakor se ti zdi dobro.«',
        38: 'Kralj je odgovoril: »Kimhám bo z menoj šel preko in storil mu bom to, kar se ti zdi dobro in karkoli boš zahteval od mene, to bom storil zate.«',
        39: 'In vse ljudstvo je šlo čez Jordan. Ko je kralj prišel čez, je kralj poljubil Barzilája in ga blagoslovil, in ta se je vrnil na svoj lasten kraj.',
        40: 'Potem je kralj odšel naprej h Gilgálu in Kimhám je z njim odšel naprej in vse Judovo ljudstvo je spremilo kralja in tudi polovica Izraelovega ljudstva.',
        41: 'Glej, vsi Izraelovi možje so prišli h kralju in kralju rekli: »Zakaj so te naši bratje, Judovi možje, ukradli in privedli kralja, njegovo družino in vse Davidove može z njim, čez Jordan?«',
        42: 'In vsi možje iz Juda so Izraelovim možem odgovorili: »Ker nam je kralj bližnji sorodnik. Zakaj ste potem jezni zaradi te zadeve? Ali smo sploh jedli na kraljeve stroške? Ali nam je dal kakršnokoli darilo?«',
        43: 'Izraelovi možje so odgovorili Judovim možem in rekli: »V kralju imamo deset delov in mi imamo več pravice do Davida kakor vi. Čemu nas potem prezirate, da naš nasvet ne bi bil prvi v tem, da smo svojega kralja privedli nazaj?« In besede mož iz Juda so bile trše kakor besede mož iz Izraela.',
    },
    20: {
        1: 'Zgodilo se je, da je bil tam Beliálov mož, katerega ime je bilo Ševá, Bihríjev sin, Benjaminovec. Ta je zatrobil na šofar in rekel: »Mi nimamo deleža v Davidu niti nimamo dediščine v Jesejevem sinu. Vsak mož k svojim šotorom, oh Izrael.«',
        2: 'Tako je vsak mož iz Izraela odšel gor izza Davida in sledil Bihríjevem sinu Ševáju; toda Judovi možje, od Jordana, celo do Jeruzalema, so se trdno pridružili njihovemu kralju.',
        3: 'David je prišel k svoji hiši v Jeruzalemu in kralj je vzel deset žensk, svojih priležnic, ki jih je pustil, da varujejo hišo in jih zaprl v ječo in jih hranil, toda ni šel noter k njim. Tako so bile zaprte do dneva svoje smrti, živeče v vdovstvu.',
        4: 'Potem je kralj rekel Amasáju: »V treh dneh mi zberi može iz Juda in ti bodi tu prisoten.«',
        5: 'Tako je Amasá odšel, da zbere Judove može, toda zadržal se je dlje kakor postavljen čas, ki mu je bil določen.',
        6: 'David je rekel Abišáju: »Sedaj nam bo Bihríjev sin Ševá storil več škode, kakor jo je storil Absalom. Vzemi služabnike svojega gospoda in ga zasleduj, da si ne pridobi utrjenih mest in nam pobegne.«',
        7: 'Tam so odšli ven za njim Joábovi možje, Keretéjci, Péletovci in vsi mogočni možje. Odšli so iz Jeruzalema, da zasledujejo Bihríjevega sina Ševája.',
        8: 'Ko so bili pri velikem kamnu, ki je v Gibeónu, je Amasá šel pred njimi. Joábova obleka, ki jo je oblekel, je bila opasana k njemu in na njej pas s pritrjenim mečem na svojih ledjih, v svoji nožnici in ko je šel naprej, je ta padel ven.',
        9: 'Joáb je rekel Amasáju: » Ali si pri zdravju, moj brat?« Joáb je z desnico prijel Amasája za brado, da ga poljubi.',
        10: 'Toda Amasá ni pazil na meč, ki je bil v Joábovi roki. Tako ga je z njim udaril v peto rebro in njegovo notranjost prelil na tla in ni ga ponovno udaril in je umrl. Tako sta Joáb in njegov brat Abišáj zasledovala Bihríjevega sina Ševája.',
        11: 'Eden izmed Joábovih mož je stal poleg njega ter rekel: »Kdor je naklonjen Joábu in kdor je za Davida, ta naj gre za Joábom.«',
        12: 'Amasá se je valjal v krvi na sredi glavne ceste. In ko je mož videl, da je vse ljudstvo obstalo, je Amasája odstranil z glavne ceste na polje in nanj vrgel oblačilo, ko je videl, da je vsak, kdor je prišel mimo, mirno obstal.',
        13: 'Ko je bil odstranjen z glavne ceste, je vse ljudstvo odšlo naprej za Joábom, da zasledujejo Bihríjevega sina Ševája.',
        14: 'Ta je šel skozi vse Izraelove rodove do Abéle in do Bet Maáhe in do vseh Bihríjevcev in zbrani so bili skupaj ter šli tudi za njim.',
        15: 'Prišli so in ga oblegali v Abél Bet Maáhi in nasuli so nasip zoper mesto in le-ta je stal v jarku. In vse ljudstvo, ki je bilo z Joábom, je uničevalo obzidje, da ga zrušijo.',
        16: 'Potem je modra ženska iz mesta zaklicala: »Poslušajte, poslušajte. Recite, prosim vas, Joábu: ›Pridi blizu sèm, da lahko govorim s teboj.‹«',
        17: 'Ko je ta prišel bliže k njej, je ženska rekla: » Ali si ti Joáb?« Odgovoril je: »Jaz sem.« Potem mu je rekla: »Poslušaj besede svoje pomočnice.« Odgovoril je: »Poslušam.«',
        18: 'Potem je spregovorila, rekoč: »V starih časih so bili navajeni govoriti, rekoč: ›Zagotovo bodo vprašali za nasvet v Abélu,‹ in tako so končali zadevo.',
        19: 'Jaz sem ena izmed tistih, ki so v Izraelu mirni in zvesti, ti pa si prizadevaš, da uničiš mesto in mater v Izraelu. Zakaj hočeš pogoltniti Gospodovo dediščino?«',
        20: 'Joáb je odgovoril in rekel: »Daleč bodi to, daleč bodi to od mene, da bi pogoltnil ali uničil.',
        21: 'Zadeva ni takšna, temveč človek z gore Efrájim, po imenu Bihríjev sin Ševá, je vzdignil svojo roko zoper kralja, celó zoper Davida. Samo njega izročite in odšel bom od mesta.« Ženska je rekla Joábu: »Glej, njegova glava ti bo vržena čez obzidje.«',
        22: 'Potem je ženska, v svoji modrosti, odšla k vsemu ljudstvu. Odsekali so glavo Bihríjevega sina Ševája in jo vrgli ven k Joábu. Ta je zatrobil na šofar in umaknili so se od mesta, vsak mož k svojemu šotoru. In Joáb se je vrnil h kralju v Jeruzalem.',
        23: 'Torej Joáb je bil nad vso Izraelovo vojsko. Jojadájev sin Benajá je bil nad Keretéjci in nad Péletovci;',
        24: 'Adorám je bil nad davkom; Ahilúdov sin Józafat je bil letopisec;',
        25: 'Ševá je bil pisar; Cadók in Abjatár sta bila duhovnika;',
        26: 'in tudi Jaírovec Irá je bil glavni častnik pri Davidu.',
    },
    21: {
        1: 'V Davidovih dneh je bila takrat tam tri leta lakota, leto za letom. David je poizvedel od Gospoda. In Gospod je odgovoril: » To je zaradi Savla in zaradi njegove krvoločne hiše, ker je pobil Gibeónce.«',
        2: 'Kralj je poklical Gibeónce in jim rekel; (torej Gibeónci niso bili izmed Izraelovih otrok, temveč od ostanka Amoréjcev in Izraelovi otroci so jim prisegli. Savel pa si je prizadeval, da jih v svoji gorečnosti do Izraelovih otrok in Juda, pokonča.)',
        3: 'Zato je David rekel Gibeóncem: »Kaj naj storim za vas? S čim naj storim spravo, da boste lahko blagoslovili Gospodovo dediščino?«',
        4: 'Gibeónci so mu rekli: »Nočemo imeti niti Savlovega srebra, niti zlata, niti njegovih hiš, niti ne boš za nas nikogar ubil v Izraelu.« Rekel je: »Kar boste rekli, to bom storil za vas.«',
        5: 'Kralju so odgovorili: »Od človeka, ki nas je použil in ki je snoval zoper nas, da bi bili mi uničeni od preostanka v vseh Izraelovih pokrajinah,',
        6: 'naj nam bo izročenih sedem mož izmed njegovih sinov in obesili jih bomo Gospodu v Savlovi Gíbei, ki ga je Gospod izbral.« Kralj je rekel: »Dal jih bom.«',
        7: 'Toda kralj je prizanesel Mefibóšetu, sinu Savlovega sina Jonatana, zaradi Gospodove prisege, ki je bila med njima, med Davidom in Savlovim sinom Jonatanom.',
        8: 'Temveč je kralj vzel dva sinova Ajájeve hčere Ricpe, ki jih je rodila Savlu, Armoníja in Mefibóšeta in pet sinov Savlove hčere Mihále, ki jih je vzgojila za Adriéla, sina Mehólčana Barzilája',
        9: 'in izročil jih je v roke Gibeóncem in obesili so jih na hribu pred Gospodom. Vseh sedem je skupaj padlo in bili so usmrčeni v dneh žetve, v prvih dneh, v začetku ječmenove žetve.',
        10: 'Ajájeva hči Ricpa pa je vzela vrečevino in jo razgrinjala na skali od začetka žetve, dokler nanje ni kapljala voda z neba in ni pustila niti pticam neba, da na njih počivajo podnevi niti živalim polja ponoči.',
        11: 'To je bilo povedano Davidu, kaj je storila Savlova priležnica, Ajájeva hči Ricpa.',
        12: 'David je odšel in vzel Savlove kosti in kosti njegovega sina Jonatana od ljudi iz Jabéš Gileáda, ki so jih ukradli iz ulice Bet Šeána, kjer so jih Filistejci obesili, ko so Filistejci umorili Savla na Gilbói.',
        13: 'Od tam je prinesel gor kosti Savla in kosti njegovega sina Jonatana in zbrali so [tudi] kosti tistih, ki so bili obešeni.',
        14: 'Kosti Savla in njegovega sina Jonatana so pokopali v Celi, v Benjaminovi deželi, v mavzoleju njegovega očeta Kiša in izpolnili so vse, kar je kralj zapovedal. Potem se je dal Bog izprositi za deželo.',
        15: 'Poleg tega so Filistejci ponovno imeli vojno z Izraelom in David je šel dol in njegovi služabniki z njim in borili so se zoper Filistejce, David pa je postal slaboten.',
        16: '§ Jišbí Benób, ki je bil izmed sinov velikana, čigar sulica je tehtala tristo šeklov brona v teži, je bil opasan z novim mečem, misleč, da bo umoril Davida.',
        17: 'Toda Cerújin sin Abišáj mu je pomagal, udaril Filistejca in ga ubil. Potem so mu Davidovi možje prisegli, rekoč: »Ne boš več šel z nami v bitko, da ne pogasiš Izraelove svetlobe.«',
        18: '§ Pripetilo se je po tem, da je bila ponovno bitka s Filistejci pri Gobu. Takrat je Hušán Sibeháj ubil Safa, ki je bil izmed sinov velikana.',
        19: 'In tam je bila ponovno bitka s Filistejci v Gobu, kjer je Elhanán, sin Betlehemca Jaaré Orgíma, usmrtil brata Gitéjca Goljata, katerega palica njegove sulice je bila podobna tkalčevemu brunu.',
        20: '§ In tam je bila spet bitka v Gatu, kjer je bil mož visoke postave, ki je imel na vsaki roki šest prstov in na vsakem stopalu šest prstov, štiriindvajset po številu, in tudi on je bil rojen velikanu.',
        21: 'Ko je izzival Izraela, ga je Jonatan, sin Davidovega brata Šimája, usmrtil.',
        22: '§ Ti štirje so bili rojeni velikanu v Gatu in padli so po Davidovi roki in po roki njegovih služabnikov.',
    },
    22: {
        1: 'David je Gospodu spregovoril besede te pesmi na dan, ko ga je Gospod osvobodil iz roke vseh njegovih sovražnikov in iz Savlove roke.',
        2: 'Rekel je: » Gospod je moja skala in moja trdnjava in moj osvoboditelj;',
        3: 'Bog moje skale; vanj bom zaupal. On je moj ščit in rog rešitve moje duše, moj visoki stolp in moje zatočišče, moj rešitelj; ti me rešuješ pred nasiljem.',
        4: 'Klical bom h Gospodu, ki je vreden, da je hvaljen. Tako bom rešen pred svojimi sovražniki.',
        5: 'Ko so me obdali valovi smrti, so me preplašile poplave brezbožnih ljudi;',
        6: 'bridkosti pekla so me obkrožile, zanke smrti so me ovirale;',
        7: 'v svoji stiski sem klical h Gospodu in jokal k svojemu Bogu. Iz svojega svetišča je slišal moj glas in moj jok je vstopil v njegova ušesa.',
        8: 'Potem se je zemlja stresla in vztrepetala, temelji neba so se premaknili in stresli, ker je bil ogorčen.',
        9: 'Iz njegovih nosnic se je dvignil dim in ogenj iz njegovih ust je požiral. Z njim so bili vžgani ogorki.',
        10: 'Upognil je tudi nebo in prišel dol in tema je bila pod njegovimi stopali.',
        11: 'Jahal je na kerubu in letel. Viden je bil na perutih vetra.',
        12: 'Vsenaokrog sebe je naredil paviljone teme, temne vode in goste oblake neba.',
        13: 'Od bleščave pred njim so bili vžgani ognjeni ogorki.',
        14: 'Gospod je zagrmel iz nebes in Najvišji je izustil svoj glas.',
        15: 'Odposlal je puščice in jih razkropil; bliskanje in jih porazil.',
        16: 'Prikazale so se morske struge, temelji zemeljskega [kroga] so bili odkriti ob Gospodovem karanju, ob puhu sape iz njegovih nosnic.',
        17: 'Poslal je od zgoraj, vzel me je, potegnil me je iz mnogih vodá,',
        18: 'osvobodil me je pred mojim močnim sovražnikom in pred tistimi, ki so me sovražili, kajti zame so bili premočni.',
        19: 'Ovirali so me na dan moje katastrofe, toda Gospod je bil moja opora.',
        20: 'Prav tako me je privedel na velik kraj. Osvobodil me je, ker se je razveseljeval v meni.',
        21: 'Gospod me je nagradil glede na mojo pravičnost. Poplačal mi je glede na čistost mojih rok.',
        22: 'Kajti držal sem se Gospodovih poti in se nisem zlobno oddvojil od svojega Boga.',
        23: 'Kajti vse njegove sodbe so bile pred menoj, in glede njegovih zakonov, se nisem ločil od njih.',
        24: 'Pred njim sem bil tudi iskren in se zadržal pred svojo krivičnostjo.',
        25: 'Zatorej mi je Gospod poplačal glede na mojo pravičnost; glede na mojo čistost v njegovem pogledu.',
        26: 'Z usmiljenim se boš pokazal usmiljenega in s poštenim človekom se boš pokazal poštenega.',
        27: 'S čistim se boš pokazal čistega in s kljubovalnim se boš pokazal neokusnega.',
        28: 'Stiskano ljudstvo boš rešil, toda tvoje oči so na ošabnih, da jih lahko privedeš dol.',
        29: 'Kajti ti si moja svetilka, oh Gospod in Gospod bo razsvetlil mojo temo.',
        30: 'Kajti s teboj sem tekel skozi krdelo, s svojim Bogom sem preskočil zid.',
        31: 'Glede Boga, njegova pot je popolna; Gospodova beseda je preizkušena. On je ščit vsem tistim, ki zaupajo vanj.',
        32: 'Kajti kdo je Bog, razen Gospoda? In kdo je skala, razen našega Boga?',
        33: 'Bog je moja sila in moč in mojo pot dela popolno.',
        34: 'Moje noge dela podobne nogam košut in me postavlja na moje visoke kraje.',
        35: '§ Moje roke uči bojevanja, tako, da je jeklen lok zlomljen z mojimi lakti.',
        36: 'Dal si mi tudi ščit tvoje rešitve duše in tvoja blagost me je naredila velikega.',
        37: 'Povečal si moje korake pod menoj, tako, da moja stopala niso zdrsnila.',
        38: 'Zasledoval sem svoje sovražnike in jih uničil in se nisem ponovno obrnil, dokler jih nisem použil.',
        39: 'Použil sem jih in jih ranil, da niso mogli vstati. Da, padli so pod mojimi stopali.',
        40: 'Kajti opasal si me z močjo za boj. Tiste, ki se vzdigujejo zoper mene, si podjarmil pod menoj.',
        41: 'Dal si mi tudi vratove mojih sovražnikov, da lahko uničim tiste, ki me sovražijo.',
        42: 'Pogledali so, toda nikogar ni bilo, da reši; celó h Gospodu, toda ni jim odgovoril.',
        43: 'Potem sem jih zdrobil v zemeljski prah, pohodil sem jih kakor ulično blato in jih raztresel naokoli.',
        44: 'Osvobodil si me tudi pred prepiri mojega ljudstva, ohranil si me, da bi bil poglavar poganom. Ljudstvo, ki ga nisem poznal, mi bo služilo.',
        45: 'Tujci se mi bodo podredili; takoj ko slišijo, mi bodo poslušni.',
        46: 'Tujci bodo bledeli in prestrašeni bodo iz svojih zaprtih krajev.',
        47: 'Gospod živi in blagoslovljena bodi moja skala in povišan bodi Bog skale rešitve moje duše.',
        48: 'To je Bog, ki me maščuje in ki ljudstvo prinaša podme',
        49: 'in ki me pelje naprej pred mojimi sovražniki. Prav tako si me dvignil na visoko, nad tiste, ki so vstali zoper mene. Osvobodil si me pred nasilnežem.',
        50: 'Zato se ti bom zahvaljeval, oh Gospod, med pogani in prepeval bom hvalnice tvojemu imenu.',
        51: 'On je stolp rešitve duš za svojega kralja in izkazuje usmiljenje svojemu maziljencu Davidu in njegovemu semenu na vékomaj.«',
    },
    23: {
        1: 'Torej to so zadnje Davidove besede. Jesejev sin David je rekel in mož, ki je bil vzdignjen na visoko, maziljenec Jakobovega Boga in prijeten Izraelov psalmist, je rekel:',
        2: '» Gospodov Duh je govoril po meni in njegova beseda je bila na mojem jeziku.',
        3: 'Izraelov Bog je rekel: ›Izraelova skala mi je spregovorila: ›Kdor vlada nad ljudmi, mora biti pravičen, vladajoč v strahu Božjem.‹‹',
        4: 'In on bo kakor svetloba jutra, ko vzhaja sonce, celó brezoblačno jutro, kakor nežna trava, ki poganja iz zemlje, s čistim sijanjem po dežju.',
        5: 'Čeprav moja hiša ni takšna z Bogom, vendar je z menoj sklenil večno zavezo, urejeno v vseh stvareh in zanesljivo. Kajti to je vsa moja rešitev duše in vsa moja želja, čeprav ji on ne daje rasti.',
        6: 'Toda Beliálovi sinovi bodo vsi izmed njih kakor zavrženo trnje, ker ne morejo biti prijeti z rokami,',
        7: 'toda človek, ki se jih bo dotaknil, mora biti ograjen z železom in palico sulice, in na istem kraju bodo popolnoma požgani z ognjem.«',
        8: 'To so imena mogočnih mož, ki jih je imel David: Tahkemoníjec, ki je sedel na sedežu, glavni izmed poveljnikov; enak je bil Ezničan Adino. Svojo sulico je vzdignil proti osemstotim, ki jih je enkrat pobil.',
        9: 'Za njim je bil Eleazar, sin Dodója, Ahóahovca, z Davidom eden izmed treh mogočnih mož, ko so izzivali Filistejce, ki so bili tam skupaj zbrani za boj in Izraelovi možje so odšli proč.',
        10: 'Ta je vstal in udarjal Filistejce, dokler njegova roka ni bila izmučena in se je njegova roka trdno oklenila meča in Gospod je tisti dan izvršil veliko zmago in ljudstvo se je vrnilo za njim, [vendar] samo da plenijo.',
        11: 'Za njim je bil Šamá, sin Hararéjca Agaja. Filistejci so bili skupaj zbrani v krdelo, kjer je bil kos polja poln leče in ljudstvo je pobegnilo pred Filistejci.',
        12: 'Toda on je stal na sredi polja in ga obranil in pobil Filistejce, in Gospod je izvršil veliko zmago.',
        13: 'Trije izmed tridesetih vodij so odšli dol in prišli k Davidu v času žetve, k votlini Adulám, in krdelo Filistejcev je taborilo v dolini Rafájim.',
        14: 'David je bil takrat v utrdbi in garnizija Filistejcev je bila takrat v Betlehemu.',
        15: 'David je hrepenel in rekel: »Oh, da bi mi nekdo dal piti od vode betlehemskega vodnjaka, ki je pri velikih vratih!«',
        16: 'Trije mogočni možje so predrli vojsko Filistejcev in zajeli vodo iz betlehemskega vodnjaka, ki je bil pri velikih vratih in jo vzeli ter jo prinesli k Davidu, pa vendar ni hotel piti od nje, temveč jo je izlil Gospodu.',
        17: 'Rekel je: »Daleč naj bo od mene, oh Gospod, da bi to storil. Mar ni to kri mož, ki so šli v nevarnosti za svoja življenja?« Zato tega ni hotel piti. Te stvari so storili ti trije mogočni možje.',
        18: 'Abišáj, Joábov brat, Cerújin sin, je bil vodja med tremi. Svojo sulico je dvignil proti tristotim in jih pobil in imel je ime med tremi.',
        19: 'Mar ni bil on najbolj častitljiv izmed treh? Zato je bil njihov poveljnik, vendar prvih treh ni dosegel.',
        20: 'Jojadájev sin Benajá, sin hrabrega moža iz Kabceéla, ki je storil mnogo dejanj, je usmrtil dva, levom podobna moža iz Moába. Odšel je tudi dol in ubil leva v sredi jame v času snega.',
        21: 'Ubil je Egipčana, čednega moža. Egipčan je imel v svoji roki sulico, toda dol k njemu je šel s palico in iztrgal sulico iz Egipčanove roke in ga ubil z njegovo lastno sulico.',
        22: 'Te stvari je storil Jojadájev sin Benajá in imel je ime med tremi mogočnimi možmi.',
        23: 'Bil je častitljivejši od tridesetih, vendar prvih treh ni dosegel. In David ga je postavil nad svojo stražo.',
        24: 'Joábov brat Asaél je bil eden izmed tridesetih: Dodójev sin Elhanán iz Betlehema,',
        25: 'Haródec Šamá, Haródec Eliká,',
        26: 'Paltičan Helec, Irá, sin Tekójčana Ikéša,',
        27: 'Anatóčan Abiézer, Hušán Mebunáj,',
        28: 'Ahóahovec Calmón, Netófčan Mahráj,',
        29: 'Heleb, sin Netófčana Baanája, Ribájev sin Itáj iz Gíbee Benjaminovih otrok,',
        30: 'Piratónec Benajá, Hidáj iz Gáaševih potokov,',
        31: 'Arbatéjec Abialbón, Barhuméjec Azmávet,',
        32: 'Šaalbónec Eljahbá, izmed Jašénovih sinov Jonatan,',
        33: 'Hararéjec Šamá, Ahiám, sin Hararéjca Šarárja,',
        34: 'Elifélet, sin Ahasbája, sin Maahčána, Eliám, sin Gilčana Ahitófela,',
        35: 'Karmélčan Hecrai, Arbéjec Paarai,',
        36: 'Natánov sin Jigál iz Cobe, Gádovec Baní,',
        37: 'Amónec Celek, Beeróčan Nahráj, nosilec bojne opreme Cerújinega sina Joába,',
        38: 'Jéterjevec Irá, Jéterjevec Garéb,',
        39: 'Hetejec Urijá; skupaj sedemintrideset.',
    },
    24: {
        1: 'In ponovno je bila vžgana Gospodova jeza zoper Izrael in zoper njih je napeljal Davida, da reče: »Pojdite, preštejte Izraela in Juda.«',
        2: 'Kajti kralj je rekel Joábu, poveljniku vojske, ki je bila z njim: »Pojdite sedaj skozi vse Izraelove rodove, od Dana, celo do Beeršébe in preštejte ljudstvo, da bom lahko vedel število ljudstva.«',
        3: 'Joáb pa je rekel kralju: »Torej Gospod, tvoj Bog, [naj] doda ljudstvu, kolikokrat že, stokratno in da bodo oči mojega gospoda kralja lahko to videle, toda zakaj se moj gospod kralj razveseljuje v tej stvari?«',
        4: 'Vendar je kraljeva beseda prevladala zoper Joába in zoper poveljnike vojske. In Joáb in poveljniki vojske so odšli izpred kraljeve prisotnosti, da preštejejo Izraelsko ljudstvo.',
        5: 'Prečkali so Jordan in se utaborili v Aroêrju, na desni strani mesta, ki leži v sredi reke Gad in proti Jazêrju.',
        6: 'Potem so prišli v Gileád in v deželo Tahtím Hodší; in prišli so v Dan Jáan in okoli k Sidónu',
        7: 'in prišli so k močnemu oporišču Tir in k vsem mestom Hivéjcev in Kánaancev in odšli so ven k južnemu Judu, celó do Beeršébe.',
        8: 'Torej ko so šli skozi vso deželo, so ob koncu devetih mesecev in dvajsetih dni prišli v Jeruzalem.',
        9: 'Joáb je kralju izročil vsoto števila ljudstva. Tam je bilo v Izraelu osemsto tisoč hrabrih mož, ki so izdirali meč in Judovih mož je bilo petsto tisoč mož.',
        10: 'Davidovo srce pa ga je udarilo, potem ko je imel ljudstvo prešteto. David je rekel Gospodu: »Silno sem grešil v tem, kar sem storil in sedaj te rotim, oh Gospod, odvzemi krivičnost svojega služabnika, kajti postopal sem zelo nespametno.«',
        11: 'Kajti ko je bil David zjutraj pokonci, je k Davidovemu vidcu, preroku Gadu, prišla beseda od Gospoda, rekoč:',
        12: '»Pojdi in reci Davidu: ›Tako govori Gospod, ponujam ti tri stvari. Izberi eno izmed njih, da ti jo lahko storim.‹«',
        13: 'Tako je Gad prišel k Davidu in mu povedal ter mu rekel: »Ali naj pride k tebi, v tvojo deželo, sedem let lakote? Ali hočeš tri mesece bežati pred svojimi sovražniki, medtem ko te zasledujejo? Ali, da bo v tvoji deželi tridnevna kužna bolezen? Sedaj se posvetuj in glej, kakšen odgovor naj vrnem tistemu, ki me je poslal.«',
        14: 'David je Gadu rekel: »V veliki stiski sem. Naj torej pademo v Gospodovo roko, kajti njegova usmiljenja so velika in naj ne padem v roko človeka.«',
        15: 'Tako je Gospod nad Izrael poslal kužno bolezen od jutra celo do določenega časa in tam je umrlo izmed ljudstva, od Dana, celo do Beeršébe, sedemdeset tisoč mož.',
        16: 'Ko je angel svojo roko iztegnil nad Jeruzalem, da ga uniči, se je Gospod pokesal od zla in rekel angelu, ki je uničeval ljudstvo: »Dovolj je. Zadrži sedaj svojo roko.« Gospodov angel pa je bil pri kraju mlatišča Jebusejca Arávna.',
        17: 'David je spregovoril Gospodu, ko je videl angela, ki je udaril ljudstvo in rekel: »Glej! Grešil sem, storil sem zlobno. Toda te ovce, kaj so storile? Naj bo tvoja roka, prosim te, zoper mene in zoper hišo mojega očeta.«',
        18: 'Gad je ta dan prišel k Davidu in mu rekel: »Pojdi gor, zgradi oltar Gospodu na mlatišču Jebusejca Arávna.«',
        19: 'David je, glede na Gadovo izjavo, odšel gor, kakor je Gospod ukazal.',
        20: 'Arávna je pogledal in zagledal kralja ter njegove služabnike prihajati proti njemu. Arávna je odšel ven in se upognil pred kraljem na svoj obraz k tlom.',
        21: 'Arávna je rekel: »Čemu je moj gospod kralj prišel k svojemu služabniku?« David je rekel: »Da od tebe kupim mlatišče, da zgradim oltar Gospodu, da bo kuga lahko ustavljena pred ljudstvom.«',
        22: 'Arávna je rekel Davidu: »Naj moj gospod kralj vzame in daruje, kar se mu zdi dobro. Glej, tukaj so voli za žgalno daritev in mlatilne priprave in druge volovske priprave za drva.«',
        23: 'Vse te stvari je Arávna, kakor kralj, dal kralju. In Arávna je rekel kralju: » Gospod, tvoj Bog, [naj] te sprejme.«',
        24: 'Kralj pa je Arávnu rekel: »Ne; temveč bom to zagotovo kupil od tebe za ceno. Niti ne bom daroval žgalne daritve Gospodu, svojemu Bogu od tega, kar me nič ne stane.« Tako je David kupil mlatišče in vole za petdeset šeklov srebra.',
        25: 'David je tam zgradil oltar Gospodu in daroval žgalne daritve in mirovne daritve. Tako je bil Gospod izprošen za deželo in kuga se je ustavila pred Izraelom.',
    },
}
